import { memo } from "react";

interface BackgroundProps {
  variant?:
    | "hub"
    | "game"
    | "ocean-hub"
    | "ocean-game"
    | "rogue-hub"
    | "pet-hub"
    | "pet-game"
    | "build-hub"
    | "build-game"
    | "build2-hub";
}

// 全局背景：深夜蓝黑 + 金紫光晕 + 星点 + 噪点
function BackgroundBase({ variant = "hub" }: BackgroundProps) {
  const isOcean = variant === "ocean-hub" || variant === "ocean-game";
  const isPet = variant === "pet-hub" || variant === "pet-game";
  const isBuild = variant === "build-hub" || variant === "build-game" || variant === "build2-hub";
  const isGame =
    variant === "game" ||
    variant === "ocean-game" ||
    variant === "pet-game" ||
    variant === "build-game";
  return (
    <div className="pointer-events-none fixed inset-0 -z-10 overflow-hidden">
      {/* 基础渐变 */}
      <div
        className="absolute inset-0"
        style={{
          background: isOcean
            ? isGame
              ? "radial-gradient(120% 100% at 50% 0%, #06222C 0%, #04141A 55%, #02080C 100%)"
              : "radial-gradient(100% 80% at 50% 30%, #082836 0%, #04141A 60%, #02080C 100%)"
            : isPet
              ? isGame
                ? "radial-gradient(120% 100% at 50% 0%, #2A1E10 0%, #18100A 55%, #0A0706 100%)"
                : "radial-gradient(100% 80% at 50% 30%, #2E1F10 0%, #18100A 60%, #0A0706 100%)"
              : isBuild
                ? isGame
                  ? "radial-gradient(120% 100% at 50% 0%, #0A1A1E 0%, #081218 55%, #050A0C 100%)"
                  : "radial-gradient(100% 80% at 50% 30%, #0C1E24 0%, #081218 60%, #050A0C 100%)"
                : isGame
                  ? "radial-gradient(120% 100% at 50% 0%, #11142A 0%, #0B0D1A 55%, #070815 100%)"
                  : "radial-gradient(100% 80% at 50% 30%, #14182F 0%, #0B0D1A 60%, #070815 100%)",
        }}
      />
      {isOcean ? (
        <>
          {/* 青蓝光晕（左上） */}
          <div
            className="absolute -left-32 -top-32 h-[480px] w-[480px] rounded-full"
            style={{
              background:
                "radial-gradient(circle, rgba(120,220,255,0.20) 0%, rgba(120,220,255,0) 70%)",
              filter: "blur(8px)",
            }}
          />
          {/* 深海光晕（右下） */}
          <div
            className="absolute -bottom-40 -right-32 h-[560px] w-[560px] rounded-full"
            style={{
              background:
                "radial-gradient(circle, rgba(46,140,171,0.22) 0%, rgba(46,140,171,0) 70%)",
              filter: "blur(8px)",
            }}
          />
          {/* 浅青光晕（右上前） */}
          <div
            className="absolute right-[-10%] top-[-8%] h-[360px] w-[360px] rounded-full"
            style={{
              background:
                "radial-gradient(circle, rgba(120,220,255,0.12) 0%, rgba(120,220,255,0) 70%)",
              filter: "blur(6px)",
            }}
          />
        </>
      ) : isPet ? (
        <>
          {/* 暖橙光晕（左上） */}
          <div
            className="absolute -left-32 -top-32 h-[480px] w-[480px] rounded-full"
            style={{
              background:
                "radial-gradient(circle, rgba(255,200,140,0.22) 0%, rgba(255,200,140,0) 70%)",
              filter: "blur(8px)",
            }}
          />
          {/* 紫晶光晕（右下） */}
          <div
            className="absolute -bottom-40 -right-32 h-[560px] w-[560px] rounded-full"
            style={{
              background:
                "radial-gradient(circle, rgba(168,85,247,0.20) 0%, rgba(168,85,247,0) 70%)",
              filter: "blur(8px)",
            }}
          />
          {/* 暖橙浅光（右上前） */}
          <div
            className="absolute right-[-10%] top-[-8%] h-[360px] w-[360px] rounded-full"
            style={{
              background:
                "radial-gradient(circle, rgba(255,122,26,0.14) 0%, rgba(255,122,26,0) 70%)",
              filter: "blur(6px)",
            }}
          />
        </>
      ) : isBuild ? (
        <>
          {/* 青绿光晕（左上） */}
          <div
            className="absolute -left-32 -top-32 h-[480px] w-[480px] rounded-full"
            style={{
              background:
                "radial-gradient(circle, rgba(61,217,166,0.20) 0%, rgba(61,217,166,0) 70%)",
              filter: "blur(8px)",
            }}
          />
          {/* 蓝紫光晕（右下） */}
          <div
            className="absolute -bottom-40 -right-32 h-[560px] w-[560px] rounded-full"
            style={{
              background:
                "radial-gradient(circle, rgba(59,123,255,0.18) 0%, rgba(59,123,255,0) 70%)",
              filter: "blur(8px)",
            }}
          />
          {/* 青绿浅光（右上前） */}
          <div
            className="absolute right-[-10%] top-[-8%] h-[360px] w-[360px] rounded-full"
            style={{
              background:
                "radial-gradient(circle, rgba(61,217,166,0.12) 0%, rgba(61,217,166,0) 70%)",
              filter: "blur(6px)",
            }}
          />
        </>
      ) : (
        <>
          {/* 金色光晕（左上） */}
          <div
            className="absolute -left-32 -top-32 h-[480px] w-[480px] rounded-full"
            style={{
              background:
                "radial-gradient(circle, rgba(232,177,74,0.18) 0%, rgba(232,177,74,0) 70%)",
              filter: "blur(8px)",
            }}
          />
          {/* 紫晶光晕（右下） */}
          <div
            className="absolute -bottom-40 -right-32 h-[560px] w-[560px] rounded-full"
            style={{
              background:
                "radial-gradient(circle, rgba(168,85,247,0.16) 0%, rgba(168,85,247,0) 70%)",
              filter: "blur(8px)",
            }}
          />
          {/* 红宝光晕（右上前） */}
          <div
            className="absolute right-[-10%] top-[-8%] h-[360px] w-[360px] rounded-full"
            style={{
              background:
                "radial-gradient(circle, rgba(255,59,92,0.10) 0%, rgba(255,59,92,0) 70%)",
              filter: "blur(6px)",
            }}
          />
        </>
      )}
      {/* 网格点阵纹理 */}
      <div
        className="absolute inset-0 opacity-[0.12]"
        style={{
          backgroundImage:
            "radial-gradient(rgba(245,240,225,0.5) 1px, transparent 1px)",
          backgroundSize: "32px 32px",
        }}
      />
      {/* 星点 */}
      <Stars />
      {/* 噪点（顶部一层） */}
      <div
        className="absolute inset-0 opacity-[0.04] mix-blend-overlay"
        style={{
          backgroundImage:
            "url(\"data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='160' height='160'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='2' stitchTiles='stitch'/></filter><rect width='100%' height='100%' filter='url(%23n)' opacity='0.6'/></svg>\")",
        }}
      />
    </div>
  );
}

const STARS = Array.from({ length: 28 }, (_, i) => ({
  id: i,
  top: Math.random() * 100,
  left: Math.random() * 100,
  size: Math.random() * 2 + 1,
  delay: Math.random() * 3.4,
  duration: Math.random() * 2.5 + 2.5,
}));

function Stars() {
  return (
    <>
      {STARS.map((s) => (
        <div
          key={s.id}
          className="absolute rounded-full bg-bone-50 animate-twinkle"
          style={{
            top: `${s.top}%`,
            left: `${s.left}%`,
            width: s.size,
            height: s.size,
            animationDelay: `${s.delay}s`,
            animationDuration: `${s.duration}s`,
          }}
        />
      ))}
    </>
  );
}

export default memo(BackgroundBase);
