import type { Progress } from "@/game/types";

const STORAGE_KEY = "crystalline.progress.v1";

const DEFAULT_PROGRESS: Progress = {
  unlockedLevel: 1,
  totalScore: 0,
  bestCombo: 0,
  records: {},
  oceanUnlocked: 1,
  oceanRecords: {},
  diamonds: 0,
  cosmetics: [],
  petUnlocked: 1,
  petRecords: {},
  buildBestScores: {},
  build2BestScores: {},
};

export function loadProgress(): Progress {
  if (typeof window === "undefined") return { ...DEFAULT_PROGRESS };
  try {
    const raw = window.localStorage.getItem(STORAGE_KEY);
    if (!raw) return { ...DEFAULT_PROGRESS };
    const parsed = JSON.parse(raw) as Partial<Progress> & {
      // 旧字段（已废弃）——用于迁移
      buildBestScore?: number;
      build2BestScore?: number;
    };
    // 迁移旧的 buildBestScore / build2BestScore（默认时长 120 秒）
    const oldBuild = parsed.buildBestScore ?? 0;
    const oldBuild2 = parsed.build2BestScore ?? 0;
    const buildBestScores = parsed.buildBestScores ?? {};
    const build2BestScores = parsed.build2BestScores ?? {};
    if (oldBuild > 0 && (buildBestScores[120] ?? 0) < oldBuild) {
      buildBestScores[120] = oldBuild;
    }
    if (oldBuild2 > 0 && (build2BestScores[120] ?? 0) < oldBuild2) {
      build2BestScores[120] = oldBuild2;
    }
    return {
      unlockedLevel: parsed.unlockedLevel ?? 1,
      totalScore: parsed.totalScore ?? 0,
      bestCombo: parsed.bestCombo ?? 0,
      records: parsed.records ?? {},
      oceanUnlocked: parsed.oceanUnlocked ?? 1,
      oceanRecords: parsed.oceanRecords ?? {},
      diamonds: parsed.diamonds ?? 0,
      cosmetics: parsed.cosmetics ?? [],
      petUnlocked: parsed.petUnlocked ?? 1,
      petRecords: parsed.petRecords ?? {},
      buildBestScores,
      build2BestScores,
    };
  } catch {
    return { ...DEFAULT_PROGRESS };
  }
}

export function saveProgress(p: Progress): void {
  if (typeof window === "undefined") return;
  try {
    window.localStorage.setItem(STORAGE_KEY, JSON.stringify(p));
  } catch {
    // ignore
  }
}

export function resetProgress(): Progress {
  const fresh = {
    ...DEFAULT_PROGRESS,
    records: {},
    oceanRecords: {},
    petRecords: {},
  };
  saveProgress(fresh);
  return fresh;
}
