import { motion } from "framer-motion";
import {
  ArrowLeft,
  ChevronRight,
  PawPrint,
  Star,
  Lock,
  Heart,
  Gift,
} from "lucide-react";
import {
  PET_LEVELS,
  PET_AVATAR,
  PET_PART_INFO,
} from "@/game/levels";
import { useGame } from "@/hooks/useGame";
import type { PetLevelConfig } from "@/game/types";

interface PetHubProps {
  onStart: (id: number) => void;
}

const RULES: { icon: React.ReactNode; title: string; desc: string }[] = [
  {
    icon: <PawPrint size={16} className="text-amber-300" />,
    title: "宠物想要玩具",
    desc: "右侧宠物头顶气泡展示当前阶段想要的玩具，棋盘上所有零件都是玩具的组成部件。",
  },
  {
    icon: <Gift size={16} className="text-amber-300" />,
    title: "消除即收集",
    desc: "每完成一次消除视为获得了被消除棋子对应颜色的零件，累计显示在底部零件栏。",
  },
  {
    icon: <Heart size={16} className="text-amber-300" />,
    title: "两阶段挑战",
    desc: "阶段1玩具集齐后，宠物会想要新的玩具进入阶段2；零件跨阶段保留累计。",
  },
  {
    icon: <Star size={16} className="text-amber-300" />,
    title: "通关判定",
    desc: "步数用完时结算：集齐阶段1玩具即通关（1星），集齐阶段2玩具为完美通关（3星）。",
  },
];

export default function PetHub({ onStart }: PetHubProps) {
  const progress = useGame((s) => s.progress);
  const goToHub = useGame((s) => s.goToHub);

  const petUnlocked = progress.petUnlocked;
  const petStars = Object.values(progress.petRecords).reduce(
    (sum, r) => sum + (r?.stars ?? 0),
    0,
  );

  return (
    <div className="relative mx-auto flex w-full max-w-6xl flex-col gap-8 px-6 py-10">
      {/* 返回 */}
      <motion.button
        type="button"
        onClick={goToHub}
        initial={{ opacity: 0, x: -8 }}
        animate={{ opacity: 1, x: 0 }}
        transition={{ duration: 0.4 }}
        className="flex items-center gap-2 self-start text-sm text-bone-300/80 transition hover:text-amber-300"
      >
        <ArrowLeft size={16} />
        返回主界面
      </motion.button>

      {/* Hero */}
      <motion.header
        initial={{ opacity: 0, y: 16 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.7, ease: "easeOut" }}
        className="flex flex-col items-center gap-3 pt-2 text-center"
      >
        <motion.div
          initial={{ letterSpacing: "0.6em", opacity: 0 }}
          animate={{ letterSpacing: "0.18em", opacity: 1 }}
          transition={{ duration: 1.1, ease: "easeOut" }}
          className="flex items-center gap-4"
        >
          <motion.span
            animate={{ y: [0, -6, 0], rotate: [0, -8, 8, 0] }}
            transition={{
              y: { duration: 2.4, repeat: Infinity, ease: "easeInOut" },
              rotate: { duration: 4, repeat: Infinity, ease: "easeInOut" },
            }}
          >
            <PawPrint size={36} className="text-amber-300" />
          </motion.span>
          <h1 className="font-display text-5xl font-black tracking-[0.18em] text-bone-50 sm:text-6xl">
            爱宠
          </h1>
        </motion.div>
        <p className="font-display text-2xl italic tracking-[0.3em] text-gradient-gold sm:text-3xl">
          Pet Secret
        </p>
        <p className="mt-1 max-w-md text-sm text-bone-300/80">
          为宠物集齐玩具零件 · 两阶段递进挑战 · 5 关递增难度
        </p>
        {/* 宠物头像展示 */}
        <div className="mt-3 flex items-center gap-3">
          {(["cat", "rabbit", "dog"] as const).map((k) => (
            <motion.span
              key={k}
              animate={{ y: [0, -4, 0] }}
              transition={{
                duration: 2,
                repeat: Infinity,
                ease: "easeInOut",
                delay: k === "cat" ? 0 : k === "rabbit" ? 0.3 : 0.6,
              }}
              style={{ fontSize: 36, lineHeight: 1 }}
            >
              {PET_AVATAR[k]}
            </motion.span>
          ))}
        </div>
      </motion.header>

      {/* 进度面板 */}
      <motion.section
        initial={{ opacity: 0, y: 12 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.6, delay: 0.25 }}
        className="grid grid-cols-2 gap-4"
      >
        <div
          className="flex items-center gap-3 rounded-2xl p-4"
          style={{
            background:
              "linear-gradient(180deg, rgba(255,200,140,0.12), rgba(168,85,247,0.05))",
            border: "1px solid rgba(255,200,140,0.22)",
          }}
        >
          <div className="grid h-9 w-9 place-items-center rounded-lg bg-ink-700/60">
            <PawPrint size={16} className="text-amber-300" />
          </div>
          <div>
            <p className="font-display text-[10px] uppercase tracking-[0.25em] text-amber-200/70">
              已解锁
            </p>
            <p className="font-display text-2xl font-bold leading-none text-bone-50">
              {Math.min(petUnlocked - 1, PET_LEVELS.length)} /{" "}
              {PET_LEVELS.length}
            </p>
          </div>
        </div>
        <div
          className="flex items-center gap-3 rounded-2xl p-4"
          style={{
            background:
              "linear-gradient(180deg, rgba(255,200,140,0.12), rgba(168,85,247,0.05))",
            border: "1px solid rgba(255,200,140,0.22)",
          }}
        >
          <div className="grid h-9 w-9 place-items-center rounded-lg bg-ink-700/60">
            <Star size={16} className="text-amber-300" />
          </div>
          <div>
            <p className="font-display text-[10px] uppercase tracking-[0.25em] text-amber-200/70">
              累计星级
            </p>
            <p className="font-display text-2xl font-bold leading-none text-bone-50">
              {petStars} / {PET_LEVELS.length * 3}
            </p>
          </div>
        </div>
      </motion.section>

      {/* 关卡轨道 */}
      <motion.section
        initial={{ opacity: 0, y: 12 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.6, delay: 0.4 }}
      >
        <div className="mb-3 flex items-center justify-between">
          <h3 className="font-display text-lg font-semibold tracking-widest text-bone-100">
            爱宠关卡
          </h3>
        </div>
        <div className="scroll-track flex gap-4 overflow-x-auto pb-4">
          {PET_LEVELS.map((l) => {
            const record = progress.petRecords[l.id];
            const isCurrent = l.id === petUnlocked;
            const unlocked = l.id <= petUnlocked;
            return (
              <PetLevelCard
                key={`pet-${l.id}`}
                level={l}
                unlocked={unlocked}
                stars={record?.stars ?? 0}
                bestScore={record?.bestScore ?? 0}
                isCurrent={isCurrent}
                onSelect={onStart}
              />
            );
          })}
          <div className="flex w-40 shrink-0 items-center justify-center text-bone-300/40">
            <div className="text-center">
              <ChevronRight size={24} className="mx-auto mb-1 opacity-40" />
              <p className="text-[10px] uppercase tracking-widest">完结</p>
            </div>
          </div>
        </div>
      </motion.section>

      {/* 玩法说明 */}
      <motion.section
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        transition={{ duration: 0.6, delay: 0.55 }}
        className="rounded-2xl p-5"
        style={{
          background:
            "linear-gradient(180deg, rgba(255,200,140,0.12), rgba(168,85,247,0.04))",
          border: "1px solid rgba(255,200,140,0.2)",
        }}
      >
        <h3 className="mb-3 font-display text-sm font-semibold uppercase tracking-[0.3em] text-amber-100">
          爱宠规则
        </h3>
        <div className="grid grid-cols-1 gap-3 sm:grid-cols-2">
          {RULES.map((r, i) => (
            <div key={i} className="flex items-start gap-3">
              <span className="mt-0.5 grid h-7 w-7 shrink-0 place-items-center rounded-lg bg-ink-900/60">
                {r.icon}
              </span>
              <div>
                <p className="text-sm font-semibold text-bone-100">{r.title}</p>
                <p className="text-[11px] leading-snug text-bone-300/80">
                  {r.desc}
                </p>
              </div>
            </div>
          ))}
        </div>
      </motion.section>

      {/* 零件图鉴 */}
      <motion.section
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        transition={{ duration: 0.6, delay: 0.65 }}
        className="glass rounded-2xl p-5"
      >
        <h3 className="mb-3 font-display text-sm font-semibold uppercase tracking-[0.3em] text-bone-100">
          零件图鉴
        </h3>
        <div className="flex flex-wrap gap-3">
          {Object.entries(PET_PART_INFO).map(([color, info]) => (
            <div
              key={color}
              className="flex items-center gap-2 rounded-xl bg-ink-900/60 px-3 py-2"
            >
              <span style={{ fontSize: 22, lineHeight: 1 }}>
                {info.emoji}
              </span>
              <span className="text-xs text-bone-300/85">{info.name}</span>
            </div>
          ))}
        </div>
      </motion.section>
    </div>
  );
}

function PetLevelCard({
  level,
  unlocked,
  stars,
  bestScore,
  isCurrent,
  onSelect,
}: {
  level: PetLevelConfig;
  unlocked: boolean;
  stars: number;
  bestScore: number;
  isCurrent: boolean;
  onSelect: (id: number) => void;
}) {
  const avatar = PET_AVATAR[level.pet];
  const petName =
    level.pet === "cat" ? "小猫" : level.pet === "rabbit" ? "小兔" : "小狗";

  return (
    <motion.button
      type="button"
      onClick={() => unlocked && onSelect(level.id)}
      disabled={!unlocked}
      whileHover={unlocked ? { y: -4 } : undefined}
      whileTap={unlocked ? { scale: 0.98 } : undefined}
      className={`relative flex h-48 w-44 shrink-0 flex-col justify-between overflow-hidden rounded-2xl p-4 text-left transition ${
        unlocked
          ? isCurrent
            ? "border-2 border-amber-400 bg-ink-700/70 shadow-[0_8px_24px_-8px_rgba(255,200,140,0.55)]"
            : "glass"
          : "cursor-not-allowed border border-bone-50/5 bg-ink-900/60"
      }`}
      aria-label={`爱宠关卡 ${level.id}${unlocked ? "" : "（未解锁）"}`}
    >
      {/* 装饰光晕 */}
      {unlocked && (
        <div
          className="pointer-events-none absolute -right-10 -top-10 h-28 w-28 rounded-full"
          style={{
            background: isCurrent
              ? "radial-gradient(circle, rgba(255,200,140,0.4) 0%, rgba(255,200,140,0) 70%)"
              : "radial-gradient(circle, rgba(168,85,247,0.18) 0%, rgba(168,85,247,0) 70%)",
          }}
        />
      )}

      {/* 头部：关卡号 + 宠物 */}
      <div className="flex items-start justify-between">
        <div>
          <p className="font-display text-[10px] uppercase tracking-[0.3em] text-bone-300/60">
            Level
          </p>
          <p className="font-display text-4xl font-bold leading-none text-bone-50">
            {level.id}
          </p>
        </div>
        {unlocked ? (
          <span
            style={{ fontSize: 30, lineHeight: 1 }}
            title={petName}
          >
            {avatar}
          </span>
        ) : (
          <Lock size={16} className="text-bone-300/40" />
        )}
      </div>

      {/* 中部：两阶段玩具 */}
      <div className="flex flex-col gap-1">
        <div className="flex items-center gap-1.5 text-[11px] text-bone-300/85">
          <span style={{ fontSize: 14, lineHeight: 1 }}>
            {level.toy1.emoji}
          </span>
          <span>{level.toy1.name}</span>
          <span className="text-bone-300/40">→</span>
          <span style={{ fontSize: 14, lineHeight: 1 }}>
            {level.toy2.emoji}
          </span>
          <span>{level.toy2.name}</span>
        </div>
        <p className="text-[10px] leading-snug text-bone-300/70">
          {level.mechanic}
        </p>
      </div>

      {/* 底部：星级 + 步数 */}
      <div>
        <div className="mb-1 flex items-center gap-0.5">
          {[0, 1, 2].map((i) => (
            <Star
              key={i}
              size={14}
              className={
                i < stars
                  ? "fill-gold-500 text-gold-500"
                  : "text-bone-300/25"
              }
            />
          ))}
        </div>
        <p className="text-[10px] uppercase tracking-widest text-bone-300/60">
          步数
        </p>
        <p className="font-sans text-sm font-semibold text-bone-100">
          {level.moves}
        </p>
        {unlocked && bestScore > 0 && (
          <p className="mt-0.5 text-[10px] text-amber-300/80">
            最高 {bestScore.toLocaleString()}
          </p>
        )}
      </div>
    </motion.button>
  );
}
