import { motion } from "framer-motion";
import { Lock, Star } from "lucide-react";
import { LEVELS } from "@/game/levels";

interface LevelCardProps {
  levelId: number;
  unlocked: boolean;
  stars: number; // 0 if not completed
  bestScore: number;
  isCurrent: boolean;
  onSelect: (id: number) => void;
}

export default function LevelCard({
  levelId,
  unlocked,
  stars,
  bestScore,
  isCurrent,
  onSelect,
}: LevelCardProps) {
  const level = LEVELS.find((l) => l.id === levelId);
  if (!level) return null;

  return (
    <motion.button
      type="button"
      onClick={() => unlocked && onSelect(levelId)}
      disabled={!unlocked}
      whileHover={unlocked ? { y: -4 } : undefined}
      whileTap={unlocked ? { scale: 0.98 } : undefined}
      className={`relative flex h-44 w-40 shrink-0 flex-col justify-between overflow-hidden rounded-2xl p-4 text-left transition ${
        unlocked
          ? isCurrent
            ? "border-2 border-gold-500 bg-ink-700/70 shadow-gold"
            : "glass"
          : "cursor-not-allowed border border-bone-50/5 bg-ink-900/60"
      }`}
      aria-label={`关卡 ${levelId}${unlocked ? "" : "（未解锁）"}`}
    >
      {/* 装饰光晕 */}
      {unlocked && (
        <div
          className="pointer-events-none absolute -right-10 -top-10 h-28 w-28 rounded-full"
          style={{
            background: isCurrent
              ? "radial-gradient(circle, rgba(232,177,74,0.35) 0%, rgba(232,177,74,0) 70%)"
              : "radial-gradient(circle, rgba(168,85,247,0.18) 0%, rgba(168,85,247,0) 70%)",
          }}
        />
      )}

      {/* 关卡号 */}
      <div className="flex items-start justify-between">
        <div>
          <p className="font-display text-[10px] uppercase tracking-[0.3em] text-bone-300/60">
            Level
          </p>
          <p className="font-display text-4xl font-bold leading-none text-bone-50">
            {levelId}
          </p>
        </div>
        {!unlocked && <Lock size={16} className="text-bone-300/40" />}
      </div>

      {/* 中部机制 */}
      <p className="text-[11px] leading-snug text-bone-300/80">
        {level.mechanic}
      </p>

      {/* 底部：星级 + 目标 */}
      <div>
        <div className="mb-1 flex items-center gap-0.5">
          {[0, 1, 2].map((i) => (
            <Star
              key={i}
              size={14}
              className={
                i < stars
                  ? "fill-gold-500 text-gold-500"
                  : "text-bone-300/25"
              }
            />
          ))}
        </div>
        <p className="text-[10px] uppercase tracking-widest text-bone-300/60">
          目标
        </p>
        <p className="font-sans text-sm font-semibold text-bone-100">
          {level.targetScore.toLocaleString()}
        </p>
        {unlocked && bestScore > 0 && (
          <p className="mt-0.5 text-[10px] text-gold-400/80">
            最高 {bestScore.toLocaleString()}
          </p>
        )}
      </div>
    </motion.button>
  );
}
