import {
  Cell,
  Grid,
  GemColor,
  Special,
  makeCell,
  newId,
  randomColor,
} from "./types";

export const ROWS = 8;
export const COLS = 8;

function inBounds(r: number, c: number): boolean {
  return r >= 0 && r < ROWS && c >= 0 && c < COLS;
}

function key(r: number, c: number): string {
  return `${r},${c}`;
}

function parseKey(k: string): { row: number; col: number } {
  const [r, c] = k.split(",").map(Number);
  return { row: r, col: c };
}

function cloneGrid(grid: Grid): Grid {
  return grid.map((row) => row.slice());
}

function swapCells(
  grid: Grid,
  r1: number,
  c1: number,
  r2: number,
  c2: number,
): Grid {
  const g = cloneGrid(grid);
  const tmp = g[r1][c1];
  g[r1][c1] = g[r2][c2];
  g[r2][c2] = tmp;
  return g;
}

interface Run {
  cells: { row: number; col: number }[];
  color: GemColor;
}

// 找到所有 3+ 同色连线（水平/垂直）
function findRuns(grid: Grid): Run[] {
  const runs: Run[] = [];

  // 水平
  for (let r = 0; r < ROWS; r++) {
    let c = 0;
    while (c < COLS) {
      const cell = grid[r][c];
      if (!cell || cell.special === "rainbow") {
        c++;
        continue;
      }
      const color = cell.color;
      let end = c + 1;
      while (end < COLS) {
        const e = grid[r][end];
        if (!e || e.special === "rainbow" || e.color !== color) break;
        end++;
      }
      if (end - c >= 3) {
        const cells: { row: number; col: number }[] = [];
        for (let i = c; i < end; i++) cells.push({ row: r, col: i });
        runs.push({ cells, color });
      }
      c = end;
    }
  }

  // 垂直
  for (let c = 0; c < COLS; c++) {
    let r = 0;
    while (r < ROWS) {
      const cell = grid[r][c];
      if (!cell || cell.special === "rainbow") {
        r++;
        continue;
      }
      const color = cell.color;
      let end = r + 1;
      while (end < ROWS) {
        const e = grid[end][c];
        if (!e || e.special === "rainbow" || e.color !== color) break;
        end++;
      }
      if (end - r >= 3) {
        const cells: { row: number; col: number }[] = [];
        for (let i = r; i < end; i++) cells.push({ row: i, col: c });
        runs.push({ cells, color });
      }
      r = end;
    }
  }

  return runs;
}

interface MatchGroup {
  cells: { row: number; col: number }[];
  color: GemColor;
  orientation: "h" | "v" | "lt";
  length: number;
  pivot: { row: number; col: number };
}

// 将 runs 合并为组（处理 L/T 形）
function groupRuns(runs: Run[]): MatchGroup[] {
  const groups: MatchGroup[] = [];
  const used = new Set<number>();

  // 合并交叉的同色 run（L/T 形）
  for (let i = 0; i < runs.length; i++) {
    if (used.has(i)) continue;
    const a = runs[i];
    // 找与 a 交叉且同色的 run
    const cross: number[] = [];
    for (let j = i + 1; j < runs.length; j++) {
      if (used.has(j)) continue;
      const b = runs[j];
      if (b.color !== a.color) continue;
      // 检查是否有共同 cell
      const aSet = new Set(a.cells.map((c) => key(c.row, c.col)));
      const shared = b.cells.some((c) => aSet.has(key(c.row, c.col)));
      if (shared) cross.push(j);
    }
    if (cross.length > 0) {
      // 合并 a 与所有 cross runs 为 L/T 组
      const allCells = new Set<string>();
      const cellList: { row: number; col: number }[] = [];
      const addCells = (cs: { row: number; col: number }[]) => {
        for (const c of cs) {
          const k = key(c.row, c.col);
          if (!allCells.has(k)) {
            allCells.add(k);
            cellList.push(c);
          }
        }
      };
      addCells(a.cells);
      // 找交叉点作为 pivot
      let pivot = a.cells[Math.floor(a.cells.length / 2)]!;
      for (const j of cross) {
        const b = runs[j];
        addCells(b.cells);
        // 找 a 与 b 的交叉 cell
        const aSet = new Set(a.cells.map((c) => key(c.row, c.col)));
        for (const c of b.cells) {
          if (aSet.has(key(c.row, c.col))) {
            pivot = c;
            break;
          }
        }
        used.add(j);
      }
      used.add(i);
      const maxLen = [a, ...cross.map((j) => runs[j])].reduce(
        (m, r) => Math.max(m, r.cells.length),
        0,
      );
      groups.push({
        cells: cellList,
        color: a.color,
        orientation: "lt",
        length: maxLen,
        pivot,
      });
    }
  }

  // 未合并的独立 run
  for (let i = 0; i < runs.length; i++) {
    if (used.has(i)) continue;
    const r = runs[i];
    const isHorizontal = r.cells[0]!.row === (r.cells[1] ?? r.cells[0])!.row;
    const pivot =
      r.cells[Math.floor(r.cells.length / 2)]!;
    groups.push({
      cells: r.cells,
      color: r.color,
      orientation: isHorizontal ? "h" : "v",
      length: r.cells.length,
      pivot,
    });
  }

  return groups;
}

export function findMatches(grid: Grid): MatchGroup[] {
  return groupRuns(findRuns(grid));
}

function specialForGroup(g: MatchGroup): Special | null {
  if (g.orientation === "lt" && g.cells.length >= 5) return "cross";
  if (g.orientation === "lt") return "bomb";
  if (g.length >= 5) return "rainbow";
  if (g.length === 4) return g.orientation === "h" ? "line_h" : "line_v";
  return null;
}

// 特殊宝石影响范围（不含自身）
function specialAffected(
  grid: Grid,
  r: number,
  c: number,
  special: Special,
  triggerColor: GemColor | null,
): { row: number; col: number }[] {
  const result: { row: number; col: number }[] = [];
  if (special === "line_h") {
    for (let cc = 0; cc < COLS; cc++) {
      if (cc !== c) result.push({ row: r, col: cc });
    }
  } else if (special === "line_v") {
    for (let rr = 0; rr < ROWS; rr++) {
      if (rr !== r) result.push({ row: rr, col: c });
    }
  } else if (special === "bomb") {
    for (let dr = -1; dr <= 1; dr++) {
      for (let dc = -1; dc <= 1; dc++) {
        if (dr === 0 && dc === 0) continue;
        const nr = r + dr;
        const nc = c + dc;
        if (inBounds(nr, nc)) result.push({ row: nr, col: nc });
      }
    }
  } else if (special === "rainbow" && triggerColor) {
    for (let rr = 0; rr < ROWS; rr++) {
      for (let cc = 0; cc < COLS; cc++) {
        const cell = grid[rr][cc];
        if (cell && cell.color === triggerColor && !(rr === r && cc === c)) {
          result.push({ row: rr, col: cc });
        }
      }
    }
  } else if (special === "cross") {
    // 十字爆：清除整行 + 整列
    for (let cc = 0; cc < COLS; cc++) {
      if (cc !== c) result.push({ row: r, col: cc });
    }
    for (let rr = 0; rr < ROWS; rr++) {
      if (rr !== r) result.push({ row: rr, col: c });
    }
  } else if (special === "nuke") {
    // 全屏清除：返回棋盘所有格子（除自身外）
    for (let rr = 0; rr < ROWS; rr++) {
      for (let cc = 0; cc < COLS; cc++) {
        if (!(rr === r && cc === c)) result.push({ row: rr, col: cc });
      }
    }
  }
  return result;
}

// 单次连锁步骤
export interface CascadeStep {
  cleared: { row: number; col: number }[];
  // 海洋模式：本步破坏泳圈的位置（棋子保留，仅 floater=false）
  floatersBroken: { row: number; col: number }[];
  // 在清除后、下落前放置的新特殊宝石
  newSpecials: {
    row: number;
    col: number;
    color: GemColor;
    special: Special;
  }[];
  // 该步骤完成后的棋盘（清除+放置+下落+补充后）
  resultingGrid: Grid;
  scoreGained: number;
  cascadeIndex: number;
  // 此次清除触发的特殊宝石类型集合（用于动画特效）
  triggeredKinds: Special[];
}

export interface ResolveResult {
  finalGrid: Grid;
  steps: CascadeStep[];
  totalScore: number;
  bestCascade: number;
}

// 主消除循环：返回每一步的中间结果
export function resolveMatches(
  grid: Grid,
  swapPos: { row: number; col: number } | null,
): ResolveResult {
  let currentGrid = cloneGrid(grid);
  const steps: CascadeStep[] = [];
  let totalScore = 0;
  let cascade = 0;
  let bestCascade = 0;

  while (cascade < 30) {
    const groups = findMatches(currentGrid);
    if (groups.length === 0) break;

    // 收集要清除的单元格
    const toClear = new Set<string>();
    const triggered: { row: number; col: number }[] = [];

    for (const g of groups) {
      for (const cell of g.cells) {
        toClear.add(key(cell.row, cell.col));
      }
      for (const cell of g.cells) {
        const c = currentGrid[cell.row][cell.col];
        if (c && c.special !== "none" && c.special !== "rainbow") {
          triggered.push({ row: cell.row, col: cell.col });
        }
      }
    }

    // 链式触发特殊宝石
    const handled = new Set<string>();
    const triggeredKinds: Special[] = [];
    while (triggered.length > 0) {
      const s = triggered.shift()!;
      const k = key(s.row, s.col);
      if (handled.has(k)) continue;
      handled.add(k);
      const cell = currentGrid[s.row][s.col];
      if (!cell) continue;
      triggeredKinds.push(cell.special);
      const affected = specialAffected(
        currentGrid,
        s.row,
        s.col,
        cell.special,
        null,
      );
      for (const a of affected) {
        const ak = key(a.row, a.col);
        if (!toClear.has(ak)) {
          toClear.add(ak);
          const ac = currentGrid[a.row][a.col];
          if (ac && ac.special !== "none" && ac.special !== "rainbow") {
            triggered.push({ row: a.row, col: a.col });
          }
        }
      }
    }

    // 决定新特殊宝石
    const newSpecials: {
      row: number;
      col: number;
      color: GemColor;
      special: Special;
    }[] = [];
    for (const g of groups) {
      const sp = specialForGroup(g);
      if (!sp) continue;
      let place = g.pivot;
      if (swapPos) {
        const inGroup = g.cells.some(
          (c) => c.row === swapPos.row && c.col === swapPos.col,
        );
        if (inGroup) place = swapPos;
      }
      newSpecials.push({
        row: place.row,
        col: place.col,
        color: g.color,
        special: sp,
      });
    }

    // 应用清除（在副本上）
    const clearedGrid = cloneGrid(currentGrid);
    for (const k of toClear) {
      const { row, col } = parseKey(k);
      clearedGrid[row][col] = null;
    }
    // 放置新特殊宝石
    for (const ns of newSpecials) {
      clearedGrid[ns.row][ns.col] = {
        id: newId(),
        color: ns.color,
        special: ns.special,
      };
    }

    // 下落 + 补充
    const droppedGrid = dropAndRefill(clearedGrid);

    // 计算分数
    const base = toClear.size * 30;
    const mult = 1 + cascade * 0.2;
    const gained = Math.round(base * mult);
    totalScore += gained;
    bestCascade = cascade;

    steps.push({
      cleared: Array.from(toClear).map(parseKey),
      floatersBroken: [],
      newSpecials,
      resultingGrid: droppedGrid,
      scoreGained: gained,
      cascadeIndex: cascade,
      triggeredKinds,
    });

    currentGrid = droppedGrid;
    cascade++;
  }

  return { finalGrid: currentGrid, steps, totalScore, bestCascade };
}

// 海洋版消除：泳圈破坏优先 + 按水位混合填充
// 含 floater 的棋子在匹配时优先破坏泳圈（floater=false），棋子保留；不含 floater 的正常消除
// waterLevel 决定填充物理：水面上方下落（顶部补充），水面下方上浮（底部补充）
export function resolveMatchesOcean(
  grid: Grid,
  swapPos: { row: number; col: number } | null,
  waterLevel: number = 0,
): ResolveResult {
  let currentGrid = cloneGrid(grid);
  const steps: CascadeStep[] = [];
  let totalScore = 0;
  let cascade = 0;
  let bestCascade = 0;

  while (cascade < 30) {
    const groups = findMatches(currentGrid);
    if (groups.length === 0) break;

    const toClear = new Set<string>();
    const floatersBroken = new Set<string>();
    const triggered: { row: number; col: number }[] = [];

    for (const g of groups) {
      for (const cell of g.cells) {
        const k = key(cell.row, cell.col);
        const c = currentGrid[cell.row][cell.col];
        if (!c) continue;
        if (c.floater) {
          // 优先破坏泳圈，棋子保留
          floatersBroken.add(k);
        } else {
          toClear.add(k);
          if (c.special !== "none" && c.special !== "rainbow") {
            triggered.push({ row: cell.row, col: cell.col });
          }
        }
      }
    }

    // 若整组都是泳圈棋子（toClear 为空且 floatersBroken 非空），仍触发泳圈破坏
    // 链式触发特殊宝石（仅来自被消除的棋子）
    const handled = new Set<string>();
    const triggeredKinds: Special[] = [];
    while (triggered.length > 0) {
      const s = triggered.shift()!;
      const k = key(s.row, s.col);
      if (handled.has(k)) continue;
      handled.add(k);
      const cell = currentGrid[s.row][s.col];
      if (!cell) continue;
      triggeredKinds.push(cell.special);
      const affected = specialAffected(
        currentGrid,
        s.row,
        s.col,
        cell.special,
        null,
      );
      for (const a of affected) {
        const ak = key(a.row, a.col);
        if (!toClear.has(ak) && !floatersBroken.has(ak)) {
          const ac = currentGrid[a.row][a.col];
          if (ac && ac.floater) {
            floatersBroken.add(ak);
          } else if (ac) {
            toClear.add(ak);
            if (ac.special !== "none" && ac.special !== "rainbow") {
              triggered.push({ row: a.row, col: a.col });
            }
          }
        }
      }
    }

    // 决定新特殊宝石：仅基于不含泳圈的匹配组
    const newSpecials: {
      row: number;
      col: number;
      color: GemColor;
      special: Special;
    }[] = [];
    for (const g of groups) {
      // 跳过完全由泳圈棋子组成的匹配组（不生成特殊宝石）
      const hasNonFloater = g.cells.some((cell) => {
        const c = currentGrid[cell.row][cell.col];
        return c && !c.floater;
      });
      if (!hasNonFloater) continue;
      const sp = specialForGroup(g);
      if (!sp) continue;
      let place = g.pivot;
      if (swapPos) {
        const inGroup = g.cells.some(
          (c) => c.row === swapPos.row && c.col === swapPos.col,
        );
        if (inGroup) place = swapPos;
      }
      // 避免将特殊宝石放在泳圈破坏位置（泳圈破坏后棋子还在）
      if (floatersBroken.has(key(place.row, place.col))) {
        const alt = g.cells.find(
          (c) => !floatersBroken.has(key(c.row, c.col)),
        );
        if (alt) place = alt;
      }
      newSpecials.push({
        row: place.row,
        col: place.col,
        color: g.color,
        special: sp,
      });
    }

    // 应用泳圈破坏（棋子保留，floater=false）
    for (const k of floatersBroken) {
      const { row, col } = parseKey(k);
      const cell = currentGrid[row][col];
      if (cell) {
        currentGrid[row][col] = { ...cell, floater: false };
      }
    }

    // 应用清除
    const clearedGrid = cloneGrid(currentGrid);
    for (const k of toClear) {
      const { row, col } = parseKey(k);
      clearedGrid[row][col] = null;
    }
    // 放置新特殊宝石
    for (const ns of newSpecials) {
      clearedGrid[ns.row][ns.col] = {
        id: newId(),
        color: ns.color,
        special: ns.special,
        floater: false,
      };
    }

    // 按水位混合填充：水面上方下落，水面下方上浮
    const risenGrid = dropAndRiseByWater(clearedGrid, waterLevel);

    // 计算分数：消除棋子 + 破坏泳圈奖励
    const clearBase = toClear.size * 30;
    const floaterBonus = floatersBroken.size * 25;
    const mult = 1 + cascade * 0.2;
    const gained = Math.round((clearBase + floaterBonus) * mult);
    totalScore += gained;
    bestCascade = cascade;

    steps.push({
      cleared: Array.from(toClear).map(parseKey),
      floatersBroken: Array.from(floatersBroken).map(parseKey),
      newSpecials,
      resultingGrid: risenGrid,
      scoreGained: gained,
      cascadeIndex: cascade,
      triggeredKinds,
    });

    currentGrid = risenGrid;
    cascade++;

    // 若本步只破坏泳圈没消除棋子，需要继续循环检测新匹配（泳圈破坏后棋子仍在）
    if (toClear.size === 0 && floatersBroken.size > 0) {
      continue;
    }
  }

  return { finalGrid: currentGrid, steps, totalScore, bestCascade };
}

// 下落与顶部补充
export function dropAndRefill(grid: Grid): Grid {
  const g = cloneGrid(grid);
  for (let c = 0; c < COLS; c++) {
    let writeRow = ROWS - 1;
    for (let r = ROWS - 1; r >= 0; r--) {
      if (g[r][c]) {
        if (writeRow !== r) {
          g[writeRow][c] = g[r][c];
          g[r][c] = null;
        }
        writeRow--;
      }
    }
    for (let r = writeRow; r >= 0; r--) {
      g[r][c] = makeCell(randomColor());
    }
  }
  return g;
}

// 海洋模式：按水位混合下落与上浮
// 水面上方（row < waterLevel）：棋子下落，顶部补充新棋子
// 水面下方（row >= waterLevel）：棋子上浮，底部补充新棋子
// 水面作为硬边界，两个区域独立处理，棋子不跨越水面
export function dropAndRiseByWater(grid: Grid, waterLevel: number): Grid {
  const g = cloneGrid(grid);
  const wl = Math.min(ROWS, Math.max(0, Math.floor(waterLevel)));
  for (let c = 0; c < COLS; c++) {
    // 水面上方区域（row 0..wl-1）：下落填充，顶部补充
    if (wl > 0) {
      let writeRow = wl - 1;
      for (let r = wl - 1; r >= 0; r--) {
        if (g[r][c]) {
          if (writeRow !== r) {
            g[writeRow][c] = g[r][c];
            g[r][c] = null;
          }
          writeRow--;
        }
      }
      for (let r = writeRow; r >= 0; r--) {
        g[r][c] = makeCell(randomColor());
      }
    }
    // 水面下方区域（row wl..ROWS-1）：上浮填充，底部补充
    if (wl < ROWS) {
      let writeRow = wl;
      for (let r = wl; r < ROWS; r++) {
        if (g[r][c]) {
          if (writeRow !== r) {
            g[writeRow][c] = g[r][c];
            g[r][c] = null;
          }
          writeRow++;
        }
      }
      for (let r = writeRow; r < ROWS; r++) {
        g[r][c] = makeCell(randomColor());
      }
    }
  }
  return g;
}

// 是否存在可走步
export function hasPossibleMove(grid: Grid): boolean {
  return findHint(grid) !== null;
}

// 寻找一个合法交换位置（用于提示功能）
export function findHint(grid: Grid): {
  from: { row: number; col: number };
  to: { row: number; col: number };
} | null {
  for (let r = 0; r < ROWS; r++) {
    for (let c = 0; c < COLS; c++) {
      // 与右交换
      if (c + 1 < COLS) {
        const a = grid[r][c];
        const b = grid[r][c + 1];
        if (a && b && (a.special === "rainbow" || b.special === "rainbow")) {
          return { from: { row: r, col: c }, to: { row: r, col: c + 1 } };
        }
        const swapped = swapCells(grid, r, c, r, c + 1);
        if (findMatches(swapped).length > 0) {
          return { from: { row: r, col: c }, to: { row: r, col: c + 1 } };
        }
      }
      // 与下交换
      if (r + 1 < ROWS) {
        const a = grid[r][c];
        const b = grid[r + 1][c];
        if (a && b && (a.special === "rainbow" || b.special === "rainbow")) {
          return { from: { row: r, col: c }, to: { row: r + 1, col: c } };
        }
        const swapped = swapCells(grid, r, c, r + 1, c);
        if (findMatches(swapped).length > 0) {
          return { from: { row: r, col: c }, to: { row: r + 1, col: c } };
        }
      }
    }
  }
  return null;
}

export function isDeadlock(grid: Grid): boolean {
  return !hasPossibleMove(grid);
}

// 重洗棋盘
export function shuffleGrid(grid: Grid): Grid {
  const cells: Cell[] = [];
  for (let r = 0; r < ROWS; r++) {
    for (let c = 0; c < COLS; c++) {
      const cell = grid[r][c];
      if (cell) cells.push(cell);
    }
  }
  for (let attempt = 0; attempt < 60; attempt++) {
    for (let i = cells.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [cells[i], cells[j]] = [cells[j], cells[i]];
    }
    const newGrid: Grid = [];
    let idx = 0;
    for (let r = 0; r < ROWS; r++) {
      const row: (Cell | null)[] = [];
      for (let c = 0; c < COLS; c++) {
        row.push(cells[idx++] ?? null);
      }
      newGrid.push(row);
    }
    if (findMatches(newGrid).length === 0 && hasPossibleMove(newGrid)) {
      return newGrid;
    }
  }
  return createBoard();
}

// 创建初始棋盘（无初始消除且有可走步）
export function createBoard(): Grid {
  let grid: Grid;
  let attempts = 0;
  do {
    grid = [];
    for (let r = 0; r < ROWS; r++) {
      const row: (Cell | null)[] = [];
      for (let c = 0; c < COLS; c++) {
        row.push(makeCell(randomColor()));
      }
      grid.push(row);
    }
    attempts++;
    if (attempts > 80) break;
  } while (findMatches(grid).length > 0 || !hasPossibleMove(grid));
  return grid;
}

// 海洋模式：在随机空位投放一个带泳圈的棋子（仅替换非空且无泳圈的棋子）
// 返回新棋盘和投放位置；若无可投放位置返回 null
export function spawnFloater(
  grid: Grid,
  waterLevel: number,
): { grid: Grid; pos: { row: number; col: number } } | null {
  // 候选：行 >= waterLevel 的棋子（水下区域优先），且非特殊、非泳圈
  const candidates: { row: number; col: number }[] = [];
  for (let r = 0; r < ROWS; r++) {
    for (let c = 0; c < COLS; c++) {
      const cell = grid[r][c];
      if (!cell) continue;
      if (cell.floater) continue;
      if (cell.special !== "none") continue;
      // 优先水面附近（waterLevel 行）及以下
      if (r >= waterLevel - 1) candidates.push({ row: r, col: c });
    }
  }
  // 若水面附近无候选，放宽到全棋盘
  const pool =
    candidates.length > 0
      ? candidates
      : (() => {
          const all: { row: number; col: number }[] = [];
          for (let r = 0; r < ROWS; r++) {
            for (let c = 0; c < COLS; c++) {
              const cell = grid[r][c];
              if (cell && !cell.floater && cell.special === "none") {
                all.push({ row: r, col: c });
              }
            }
          }
          return all;
        })();
  if (pool.length === 0) return null;
  const pick = pool[Math.floor(Math.random() * pool.length)]!;
  const g = cloneGrid(grid);
  const old = g[pick.row][pick.col]!;
  g[pick.row][pick.col] = {
    id: old.id,
    color: old.color,
    special: "none",
    floater: true,
  };
  return { grid: g, pos: pick };
}

// 处理交换：返回结果（成功或失败）
export interface SwapResult {
  success: boolean;
  // 交换后立即显示的棋盘（视觉交换，让玩家看到移动过程）
  swappedGrid: Grid;
  // 全部连锁完成后的最终棋盘
  finalGrid: Grid;
  steps: CascadeStep[];
  totalScore: number;
  bestCascade: number;
  // 是否触发了彩虹效果（用于动画）
  rainbowTriggered?: boolean;
  // 彩虹清除的单元格（用于动画）
  rainbowCleared?: { row: number; col: number }[];
}

export function trySwap(
  grid: Grid,
  r1: number,
  c1: number,
  r2: number,
  c2: number,
): SwapResult {
  // 不相邻：直接失败，不做视觉交换
  if (Math.abs(r1 - r2) + Math.abs(c1 - c2) !== 1) {
    return {
      success: false,
      swappedGrid: grid,
      finalGrid: grid,
      steps: [],
      totalScore: 0,
      bestCascade: 0,
    };
  }
  const a = grid[r1][c1];
  const b = grid[r2][c2];
  if (!a || !b) {
    return {
      success: false,
      swappedGrid: grid,
      finalGrid: grid,
      steps: [],
      totalScore: 0,
      bestCascade: 0,
    };
  }

  // 视觉交换视图（始终计算，用于显示移动过程）
  const swappedView = swapCells(grid, r1, c1, r2, c2);

  // 双彩虹：清屏
  if (a.special === "rainbow" && b.special === "rainbow") {
    const cleared: { row: number; col: number }[] = [];
    const clearedGrid: Grid = grid.map((row) => row.map(() => null));
    for (let r = 0; r < ROWS; r++) {
      for (let c = 0; c < COLS; c++) cleared.push({ row: r, col: c });
    }
    const refilled = dropAndRefill(clearedGrid);
    const score = cleared.length * 40;
    const resolve = resolveMatches(refilled, null);
    return {
      success: true,
      swappedGrid: swappedView,
      finalGrid: resolve.finalGrid,
      steps: [
        {
          cleared,
          floatersBroken: [],
          newSpecials: [],
          resultingGrid: refilled,
          scoreGained: score,
          cascadeIndex: 0,
          triggeredKinds: ["rainbow"],
        },
        ...resolve.steps,
      ],
      totalScore: score + resolve.totalScore,
      bestCascade: resolve.bestCascade,
      rainbowTriggered: true,
      rainbowCleared: cleared,
    };
  }

  // 单彩虹 + 普通/特殊
  if (a.special === "rainbow" || b.special === "rainbow") {
    const rainbowPos = a.special === "rainbow" ? { r: r1, c: c1 } : { r: r2, c: c2 };
    const otherPos = a.special === "rainbow" ? { r: r2, c: c2 } : { r: r1, c: c1 };
    const otherCell = grid[otherPos.r][otherPos.c]!;
    const triggerColor = otherCell.color;

    const toClear = new Set<string>();
    toClear.add(key(rainbowPos.r, rainbowPos.c));
    const triggered: { row: number; col: number }[] = [];
    for (let r = 0; r < ROWS; r++) {
      for (let c = 0; c < COLS; c++) {
        const cell = grid[r][c];
        if (!cell) continue;
        if (cell.color === triggerColor) {
          toClear.add(key(r, c));
          if (cell.special !== "none" && cell.special !== "rainbow") {
            triggered.push({ row: r, col: c });
          }
        }
      }
    }
    const handled = new Set<string>();
    while (triggered.length > 0) {
      const s = triggered.shift()!;
      const k = key(s.row, s.col);
      if (handled.has(k)) continue;
      handled.add(k);
      const cell = grid[s.row][s.col];
      if (!cell) continue;
      const affected = specialAffected(grid, s.row, s.col, cell.special, null);
      for (const af of affected) {
        const ak = key(af.row, af.col);
        if (!toClear.has(ak)) {
          toClear.add(ak);
          const ac = grid[af.row][af.col];
          if (ac && ac.special !== "none" && ac.special !== "rainbow") {
            triggered.push({ row: af.row, col: af.col });
          }
        }
      }
    }
    const clearedGrid = cloneGrid(grid);
    const clearedList = Array.from(toClear).map(parseKey);
    for (const k of toClear) {
      const { row, col } = parseKey(k);
      clearedGrid[row][col] = null;
    }
    const refilled = dropAndRefill(clearedGrid);
    const score = clearedList.length * 40;
    const resolve = resolveMatches(refilled, null);
    return {
      success: true,
      swappedGrid: swappedView,
      finalGrid: resolve.finalGrid,
      steps: [
        {
          cleared: clearedList,
          floatersBroken: [],
          newSpecials: [],
          resultingGrid: refilled,
          scoreGained: score,
          cascadeIndex: 0,
          triggeredKinds: ["rainbow"],
        },
        ...resolve.steps,
      ],
      totalScore: score + resolve.totalScore,
      bestCascade: resolve.bestCascade,
      rainbowTriggered: true,
      rainbowCleared: clearedList,
    };
  }

  // 普通交换
  if (findMatches(swappedView).length === 0) {
    // 非法交换：返回视觉交换视图，store 会延迟后还原
    return {
      success: false,
      swappedGrid: swappedView,
      finalGrid: grid,
      steps: [],
      totalScore: 0,
      bestCascade: 0,
    };
  }
  const resolve = resolveMatches(swappedView, { row: r2, col: c2 });
  return {
    success: true,
    swappedGrid: swappedView,
    finalGrid: resolve.finalGrid,
    steps: resolve.steps,
    totalScore: resolve.totalScore,
    bestCascade: resolve.bestCascade,
  };
}

// 海洋版交换：按水位混合物理（水面上方下落 / 水面下方上浮） + 泳圈破坏优先
export function trySwapOcean(
  grid: Grid,
  r1: number,
  c1: number,
  r2: number,
  c2: number,
  waterLevel: number = 0,
): SwapResult {
  if (Math.abs(r1 - r2) + Math.abs(c1 - c2) !== 1) {
    return {
      success: false,
      swappedGrid: grid,
      finalGrid: grid,
      steps: [],
      totalScore: 0,
      bestCascade: 0,
    };
  }
  const a = grid[r1][c1];
  const b = grid[r2][c2];
  if (!a || !b) {
    return {
      success: false,
      swappedGrid: grid,
      finalGrid: grid,
      steps: [],
      totalScore: 0,
      bestCascade: 0,
    };
  }

  const swappedView = swapCells(grid, r1, c1, r2, c2);

  // 双彩虹：清屏（海洋版按水位混合填充）
  if (a.special === "rainbow" && b.special === "rainbow") {
    const cleared: { row: number; col: number }[] = [];
    const clearedGrid: Grid = grid.map((row) => row.map(() => null));
    for (let r = 0; r < ROWS; r++) {
      for (let c = 0; c < COLS; c++) cleared.push({ row: r, col: c });
    }
    const refilled = dropAndRiseByWater(clearedGrid, waterLevel);
    const score = cleared.length * 40;
    const resolve = resolveMatchesOcean(refilled, null, waterLevel);
    return {
      success: true,
      swappedGrid: swappedView,
      finalGrid: resolve.finalGrid,
      steps: [
        {
          cleared,
          floatersBroken: [],
          newSpecials: [],
          resultingGrid: refilled,
          scoreGained: score,
          cascadeIndex: 0,
          triggeredKinds: ["rainbow"],
        },
        ...resolve.steps,
      ],
      totalScore: score + resolve.totalScore,
      bestCascade: resolve.bestCascade,
      rainbowTriggered: true,
      rainbowCleared: cleared,
    };
  }

  // 单彩虹 + 普通/特殊
  if (a.special === "rainbow" || b.special === "rainbow") {
    const rainbowPos = a.special === "rainbow" ? { r: r1, c: c1 } : { r: r2, c: c2 };
    const otherPos = a.special === "rainbow" ? { r: r2, c: c2 } : { r: r1, c: c1 };
    const otherCell = grid[otherPos.r][otherPos.c]!;
    const triggerColor = otherCell.color;

    const toClear = new Set<string>();
    const floatersBroken = new Set<string>();
    toClear.add(key(rainbowPos.r, rainbowPos.c));
    const triggered: { row: number; col: number }[] = [];
    for (let r = 0; r < ROWS; r++) {
      for (let c = 0; c < COLS; c++) {
        const cell = grid[r][c];
        if (!cell) continue;
        if (cell.color === triggerColor) {
          if (cell.floater) {
            floatersBroken.add(key(r, c));
          } else {
            toClear.add(key(r, c));
            if (cell.special !== "none" && cell.special !== "rainbow") {
              triggered.push({ row: r, col: c });
            }
          }
        }
      }
    }
    const handled = new Set<string>();
    while (triggered.length > 0) {
      const s = triggered.shift()!;
      const k = key(s.row, s.col);
      if (handled.has(k)) continue;
      handled.add(k);
      const cell = grid[s.row][s.col];
      if (!cell) continue;
      const affected = specialAffected(grid, s.row, s.col, cell.special, null);
      for (const af of affected) {
        const ak = key(af.row, af.col);
        if (!toClear.has(ak) && !floatersBroken.has(ak)) {
          const ac = grid[af.row][af.col];
          if (ac && ac.floater) {
            floatersBroken.add(ak);
          } else if (ac) {
            toClear.add(ak);
            if (ac.special !== "none" && ac.special !== "rainbow") {
              triggered.push({ row: af.row, col: af.col });
            }
          }
        }
      }
    }
    // 应用泳圈破坏
    const workGrid = cloneGrid(grid);
    for (const k of floatersBroken) {
      const { row, col } = parseKey(k);
      const cell = workGrid[row][col];
      if (cell) workGrid[row][col] = { ...cell, floater: false };
    }
    const clearedGrid = cloneGrid(workGrid);
    const clearedList = Array.from(toClear).map(parseKey);
    for (const k of toClear) {
      const { row, col } = parseKey(k);
      clearedGrid[row][col] = null;
    }
    const refilled = dropAndRiseByWater(clearedGrid, waterLevel);
    const score = clearedList.length * 40 + floatersBroken.size * 25;
    const resolve = resolveMatchesOcean(refilled, null, waterLevel);
    return {
      success: true,
      swappedGrid: swappedView,
      finalGrid: resolve.finalGrid,
      steps: [
        {
          cleared: clearedList,
          floatersBroken: Array.from(floatersBroken).map(parseKey),
          newSpecials: [],
          resultingGrid: refilled,
          scoreGained: score,
          cascadeIndex: 0,
          triggeredKinds: ["rainbow"],
        },
        ...resolve.steps,
      ],
      totalScore: score + resolve.totalScore,
      bestCascade: resolve.bestCascade,
      rainbowTriggered: true,
      rainbowCleared: clearedList,
    };
  }

  // 普通交换（海洋版）
  if (findMatches(swappedView).length === 0) {
    return {
      success: false,
      swappedGrid: swappedView,
      finalGrid: grid,
      steps: [],
      totalScore: 0,
      bestCascade: 0,
    };
  }
  const resolve = resolveMatchesOcean(swappedView, { row: r2, col: c2 }, waterLevel);
  return {
    success: true,
    swappedGrid: swappedView,
    finalGrid: resolve.finalGrid,
    steps: resolve.steps,
    totalScore: resolve.totalScore,
    bestCascade: resolve.bestCascade,
  };
}
