import { AnimatePresence, motion } from "framer-motion";
import CellView from "./CellView";
import { COLS, ROWS } from "@/game/engine";
import { useGame } from "@/hooks/useGame";

interface BoardProps {
  cellSize: number;
}

export default function Board({ cellSize }: BoardProps) {
  const grid = useGame((s) => s.grid);
  const selected = useGame((s) => s.selected);
  const hint = useGame((s) => s.hint);
  const clearingCells = useGame((s) => s.clearingCells);
  const phase = useGame((s) => s.phase);
  const selectCell = useGame((s) => s.selectCell);
  const activeEffect = useGame((s) => s.activeEffect);
  const mode = useGame((s) => s.mode);
  const waterLevel = useGame((s) => s.waterLevel);

  const boardSize = ROWS * cellSize;
  const interactive = phase === "idle" || phase === "settled";
  const isOcean = mode === "ocean";
  const isPet = mode === "pet";
  const isBuild = mode === "build" || mode === "build2";
  // 水面 y 坐标（棋盘内）
  const waterY = Math.min(boardSize, Math.max(0, waterLevel * cellSize));

  const isClearing = (r: number, c: number) =>
    clearingCells.some((cc) => cc.row === r && cc.col === c);

  const isSelected = (r: number, c: number) =>
    selected?.row === r && selected?.col === c;

  const isHint = (r: number, c: number) =>
    hint != null &&
    ((hint.from.row === r && hint.from.col === c) ||
      (hint.to.row === r && hint.to.col === c));

  const cells: {
    id: string;
    color: import("@/game/types").GemColor;
    special: import("@/game/types").Special;
    floater?: boolean;
    row: number;
    col: number;
  }[] = [];
  for (let r = 0; r < ROWS; r++) {
    for (let c = 0; c < COLS; c++) {
      const cell = grid[r][c];
      if (!cell) continue;
      cells.push({ ...cell, row: r, col: c });
    }
  }

  return (
    <div
      className={`relative rounded-[20px] p-3 shadow-[0_30px_60px_-20px_rgba(0,0,0,0.7),inset_0_1px_0_rgba(245,240,225,0.06)] ${
        isOcean ? "ocean-board-bg" : "board-bg"
      }`}
      style={{ width: boardSize + 24, height: boardSize + 24 }}
    >
      {/* 全屏特效层 */}
      {activeEffect === "rainbow" && (
        <div
          className="pointer-events-none absolute inset-0 rounded-[20px] z-30"
          style={{
            background:
              "radial-gradient(circle at 50% 50%, rgba(255,255,255,0.18) 0%, rgba(255,255,255,0) 60%)",
          }}
        />
      )}
      <div className="relative" style={{ width: boardSize, height: boardSize }}>
        {/* 格背板 */}
        {Array.from({ length: ROWS * COLS }).map((_, i) => {
          const r = Math.floor(i / COLS);
          const c = i % COLS;
          return (
            <div
              key={`bg-${r}-${c}`}
              className={`absolute rounded-md ${
                isOcean && r >= waterLevel ? "ocean-cell-bg" : "cell-bg"
              }`}
              style={{
                width: cellSize - 4,
                height: cellSize - 4,
                left: c * cellSize + 2,
                top: r * cellSize + 2,
              }}
            />
          );
        })}

        {/* 海洋模式：水下蓝绿滤镜 */}
        {isOcean && waterY < boardSize && (
          <div
            className="pointer-events-none absolute left-0 right-0 z-20 overflow-hidden"
            style={{
              top: waterY,
              height: boardSize - waterY,
              background:
                "linear-gradient(180deg, rgba(46,140,171,0.32) 0%, rgba(20,80,120,0.5) 100%)",
              backdropFilter: "blur(0.5px)",
            }}
          >
            {/* 水下光斑 */}
            <div className="absolute inset-0 opacity-40">
              <div
                className="absolute h-1 w-full rounded-full"
                style={{
                  top: "20%",
                  background:
                    "linear-gradient(90deg, transparent, rgba(180,240,255,0.4), transparent)",
                }}
              />
              <div
                className="absolute h-1 w-full rounded-full"
                style={{
                  top: "55%",
                  background:
                    "linear-gradient(90deg, transparent, rgba(180,240,255,0.3), transparent)",
                }}
              />
            </div>
          </div>
        )}

        {/* 海洋模式：水面线 */}
        {isOcean && waterY > 0 && waterY < boardSize && (
          <motion.div
            className="pointer-events-none absolute left-0 right-0 z-20"
            style={{ top: waterY - 2, height: 4 }}
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ duration: 0.4 }}
          >
            <div
              className="h-full w-full"
              style={{
                background:
                  "linear-gradient(90deg, rgba(120,220,255,0.2) 0%, rgba(180,240,255,0.9) 50%, rgba(120,220,255,0.2) 100%)",
                boxShadow:
                  "0 0 12px rgba(120,220,255,0.6), 0 -2px 8px rgba(180,240,255,0.4)",
              }}
            />
            {/* 水面波纹 */}
            <motion.div
              className="absolute left-0 right-0"
              style={{ top: -1, height: 6 }}
              animate={{ x: [0, 8, 0, -8, 0] }}
              transition={{ duration: 3, repeat: Infinity, ease: "easeInOut" }}
            >
              <div
                className="h-full w-full opacity-60"
                style={{
                  background:
                    "repeating-linear-gradient(90deg, transparent 0px, rgba(180,240,255,0.5) 4px, transparent 8px)",
                }}
              />
            </motion.div>
          </motion.div>
        )}

        {/* 宝石层 */}
        <AnimatePresence mode="popLayout" initial={false}>
          {cells.map((cell) => {
            const isUnderwater = isOcean && cell.row >= waterLevel;
            return (
              <CellView
                key={cell.id}
                cell={cell}
                row={cell.row}
                col={cell.col}
                size={cellSize}
                selected={isSelected(cell.row, cell.col)}
                clearing={isClearing(cell.row, cell.col)}
                hinted={isHint(cell.row, cell.col)}
                interactive={interactive}
                underwater={isUnderwater}
                partMode={isPet || isBuild}
                onClick={() => interactive && selectCell(cell.row, cell.col)}
              />
            );
          })}
        </AnimatePresence>
      </div>
    </div>
  );
}
