import { motion, AnimatePresence } from "framer-motion";
import { Home, Lightbulb, Pause, RotateCcw, Sparkles, Zap, Waves, Gem } from "lucide-react";
import { useGame } from "@/hooks/useGame";
import { getLevel, getOceanLevel, getPetLevel } from "@/game/levels";
import { ROWS } from "@/game/engine";

interface StatusBarProps {
  onHome: () => void;
  onRestart: () => void;
  onTogglePause: () => void;
  paused: boolean;
}

export default function StatusBar({
  onHome,
  onRestart,
  onTogglePause,
  paused,
}: StatusBarProps) {
  const levelId = useGame((s) => s.currentLevelId);
  const score = useGame((s) => s.score);
  const movesLeft = useGame((s) => s.movesLeft);
  const combo = useGame((s) => s.combo);
  const bestComboThisRun = useGame((s) => s.bestComboThisRun);
  const phase = useGame((s) => s.phase);
  const showHint = useGame((s) => s.showHint);
  const mode = useGame((s) => s.mode);
  const waterLevel = useGame((s) => s.waterLevel);
  const rogueActiveMult = useGame((s) => s.rogueActiveMult);
  const rogueRunBoost = useGame((s) => s.rogueRunBoost);
  const rogueNextBoost = useGame((s) => s.rogueNextBoost);
  const diamonds = useGame((s) => s.progress.diamonds);

  const isOcean = mode === "ocean";
  const isRogue = mode === "rogue";
  const isPet = mode === "pet";
  const isBuild = mode === "build" || mode === "build2";
  const petLevel = isPet ? getPetLevel(levelId) : undefined;
  const level = isOcean
    ? getOceanLevel(levelId)
    : isPet || isBuild
      ? undefined
      : getLevel(levelId);
  const target = level?.targetScore ?? 0;
  // Pet / Build 模式无 targetScore，进度条不展示
  const progress = isPet || isBuild ? 0 : Math.min(100, (score / target) * 100);
  // 水位进度：0=全淹没，100=全浮出
  const waterProgress = isOcean ? Math.round((waterLevel / ROWS) * 100) : 0;

  return (
    <div className="flex w-full flex-col gap-4">
      {/* 顶部操作栏 */}
      <div className="flex items-center justify-between">
        <div>
          <p className="font-display text-xs uppercase tracking-[0.3em] text-bone-300/70">
            {isBuild ? "Build" : "Level"}
          </p>
          <h2 className="font-display text-3xl font-bold text-bone-50">
            {isBuild ? (
              <span className="text-emerald-300">构筑</span>
            ) : (
              <>
                第 <span className="text-gradient-gold">{levelId}</span> 关
              </>
            )}
          </h2>
        </div>
        <div className="flex items-center gap-2">
          <button
            type="button"
            onClick={showHint}
            className="grid h-10 w-10 place-items-center rounded-xl glass text-bone-100 transition hover:text-emerald"
            aria-label="提示"
            title="提示合法交换"
          >
            <Lightbulb size={18} />
          </button>
          <button
            type="button"
            onClick={onHome}
            className="grid h-10 w-10 place-items-center rounded-xl glass text-bone-100 transition hover:text-gold-400"
            aria-label="返回主界面"
          >
            <Home size={18} />
          </button>
          <button
            type="button"
            onClick={onTogglePause}
            className="grid h-10 w-10 place-items-center rounded-xl glass text-bone-100 transition hover:text-gold-400"
            aria-label={paused ? "继续" : "暂停"}
          >
            <Pause size={18} />
          </button>
          <button
            type="button"
            onClick={onRestart}
            className="grid h-10 w-10 place-items-center rounded-xl glass text-bone-100 transition hover:text-gold-400"
            aria-label="重新开始"
          >
            <RotateCcw size={18} />
          </button>
        </div>
      </div>

      {/* 得分进度条 */}
      <div className="glass rounded-2xl p-4">
        <div className="flex items-end justify-between">
          <div>
            <p className="font-display text-[11px] uppercase tracking-[0.25em] text-bone-300/70">
              得分
            </p>
            <motion.p
              key={score}
              initial={{ scale: 1.15, color: "#F2C75E" }}
              animate={{ scale: 1, color: "#F5F0E1" }}
              transition={{ duration: 0.4 }}
              className="font-display text-3xl font-bold leading-none"
            >
              {score.toLocaleString()}
            </motion.p>
          </div>
          {!isPet && !isBuild ? (
            <p className="font-sans text-xs text-bone-300/70">
              目标 <span className="text-bone-50">{target.toLocaleString()}</span>
            </p>
          ) : (
            <p className="font-sans text-[10px] text-bone-300/50">
              {isBuild ? "无尽模式" : "（仅展示）"}
            </p>
          )}
        </div>
        {!isPet && !isBuild && (
          <div className="mt-3 h-2 overflow-hidden rounded-full bg-ink-700/80">
            <motion.div
              className="h-full rounded-full"
              style={{
                background:
                  "linear-gradient(90deg, #C8902D 0%, #E8B14A 50%, #F2C75E 100%)",
                boxShadow: "0 0 12px rgba(232,177,74,0.6)",
              }}
              initial={false}
              animate={{ width: `${progress}%` }}
              transition={{ type: "spring", stiffness: 120, damping: 20 }}
            />
          </div>
        )}
      </div>

      {/* 步数 + 连击（build 模式只显示连击） */}
      <div className={`grid gap-3 ${isBuild ? "grid-cols-1" : "grid-cols-2"}`}>
        {!isBuild && (
          <div className="glass rounded-2xl p-4">
            <p className="font-display text-[11px] uppercase tracking-[0.25em] text-bone-300/70">
              剩余步数
            </p>
            <motion.p
              key={movesLeft}
              initial={{ scale: 1.2, color: movesLeft <= 5 ? "#FF3B5C" : "#F2C75E" }}
              animate={{ scale: 1, color: movesLeft <= 5 ? "#FF8194" : "#F5F0E1" }}
              transition={{ duration: 0.35 }}
              className="font-display text-4xl font-bold leading-none"
            >
              {movesLeft}
            </motion.p>
          </div>
        )}
        <div className="glass rounded-2xl p-4">
          <p className="font-display text-[11px] uppercase tracking-[0.25em] text-bone-300/70">
            最大连击
          </p>
          <div className="flex items-baseline gap-1">
            <Zap
              size={18}
              className={bestComboThisRun > 0 ? "text-gold-400" : "text-bone-300/40"}
            />
            <AnimatePresence mode="popLayout">
              {bestComboThisRun > 0 ? (
                <motion.p
                  key={`best-${bestComboThisRun}`}
                  initial={{ scale: 1.4, opacity: 0 }}
                  animate={{ scale: 1, opacity: 1 }}
                  exit={{ scale: 0.8, opacity: 0 }}
                  transition={{ duration: 0.25 }}
                  className="font-display text-4xl font-bold leading-none text-gold-400"
                >
                  ×{bestComboThisRun + 1}
                </motion.p>
              ) : (
                <motion.p
                  key="best-zero"
                  className="font-display text-4xl font-bold leading-none text-bone-300/40"
                >
                  ×1
                </motion.p>
              )}
            </AnimatePresence>
          </div>
        </div>
      </div>

      {/* 当前机制提示 */}
      {(level ?? petLevel) && (
        <div className="glass flex items-center gap-2 rounded-2xl p-3">
          <Sparkles size={14} className="text-gold-400" />
          <p className="text-xs text-bone-300">
            {(level ?? petLevel)?.mechanic}
          </p>
        </div>
      )}

      {/* 海洋模式：水位进度 */}
      {isOcean && (
        <div
          className="rounded-2xl p-4"
          style={{
            background:
              "linear-gradient(180deg, rgba(120,220,255,0.10), rgba(46,140,171,0.04))",
            border: "1px solid rgba(120,220,255,0.18)",
          }}
        >
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2">
              <Waves size={14} className="text-cyan-200" />
              <p className="font-display text-[11px] uppercase tracking-[0.25em] text-cyan-200/80">
                水位
              </p>
            </div>
            <p className="font-display text-xs text-bone-300/70">
              浮出 <span className="text-cyan-100">{waterProgress}%</span>
            </p>
          </div>
          <div className="mt-2 h-2 overflow-hidden rounded-full bg-ink-700/80">
            <motion.div
              className="h-full rounded-full"
              style={{
                background:
                  "linear-gradient(90deg, #2E8CAB 0%, #78DCFF 50%, #B4F0FF 100%)",
                boxShadow: "0 0 12px rgba(120,220,255,0.55)",
              }}
              initial={false}
              animate={{ width: `${waterProgress}%` }}
              transition={{ type: "spring", stiffness: 120, damping: 20 }}
            />
          </div>
        </div>
      )}

      {/* Rogue 模式：本关加成与钻石 */}
      {isRogue && (
        <div
          className="rounded-2xl p-4"
          style={{
            background:
              "linear-gradient(180deg, rgba(232,177,74,0.12), rgba(168,85,247,0.06))",
            border: "1px solid rgba(232,177,74,0.22)",
          }}
        >
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2">
              <Sparkles size={14} className="text-gold-400" />
              <p className="font-display text-[11px] uppercase tracking-[0.25em] text-gold-400/80">
                本关加成
              </p>
            </div>
            <p className="font-display text-sm font-bold text-gradient-gold">
              ×{rogueActiveMult.toFixed(2)}
            </p>
          </div>
          <div className="mt-2 flex flex-wrap items-center gap-x-3 gap-y-1 text-[11px] text-bone-300/80">
            <span>全程 +{Math.round(rogueRunBoost * 100)}%</span>
            {rogueNextBoost > 0 && (
              <span className="text-gold-400">
                下关 +{Math.round(rogueNextBoost * 100)}%
              </span>
            )}
            <span className="ml-auto flex items-center gap-1 text-gold-400">
              <Gem size={12} />
              {diamonds.toLocaleString()}
            </span>
          </div>
        </div>
      )}

      {/* 阶段提示 */}
      <AnimatePresence>
        {phase === "cascade" && combo > 0 && (
          <motion.div
            initial={{ opacity: 0, y: 8 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -8 }}
            className="pointer-events-none flex items-center justify-center gap-2 rounded-xl bg-gold-500/15 px-3 py-2 text-gold-400"
          >
            <Zap size={14} />
            <span className="text-xs font-semibold uppercase tracking-widest">
              连锁中
            </span>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}
