import { motion } from "framer-motion";
import Gem from "./Gem";
import ToyPart from "./ToyPart";
import type { Cell as CellType } from "@/game/types";

interface CellViewProps {
  cell: CellType;
  row: number;
  col: number;
  size: number;
  selected: boolean;
  clearing: boolean;
  hinted: boolean;
  interactive: boolean;
  // 海洋模式：是否在水下
  underwater: boolean;
  // 爱宠大机密模式：渲染零件图标替代宝石
  partMode?: boolean;
  onClick: () => void;
}

export default function CellView({
  cell,
  row,
  col,
  size,
  selected,
  clearing,
  hinted,
  interactive,
  underwater,
  partMode = false,
  onClick,
}: CellViewProps) {
  return (
    <motion.button
      type="button"
      layout
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0, scale: 0.2 }}
      transition={{
        layout: { type: "spring", stiffness: 380, damping: 30, mass: 0.7 },
        opacity: { duration: 0.16 },
        scale: { duration: 0.2 },
      }}
      onClick={onClick}
      disabled={!interactive}
      aria-label={`宝石 ${cell.color}${cell.special !== "none" ? "（特殊）" : ""}，第 ${row + 1} 行 ${col + 1} 列`}
      className={`absolute grid place-items-center outline-none ${
        interactive ? "cursor-pointer" : "cursor-default"
      } ${selected ? "z-20" : "z-10"} ${underwater ? "underwater-cell" : ""}`}
      style={{
        width: size,
        height: size,
        left: col * size,
        top: row * size,
      }}
    >
      {/* 选中态光环 */}
      {selected && (
        <motion.span
          className="absolute rounded-full"
          initial={{ opacity: 0.4, scale: 0.9 }}
          animate={{ opacity: [0.4, 0.85, 0.4], scale: [0.95, 1.05, 0.95] }}
          transition={{ duration: 1.6, repeat: Infinity, ease: "easeInOut" }}
          style={{
            width: size * 0.92,
            height: size * 0.92,
            boxShadow:
              "0 0 0 2px rgba(232,177,74,0.9), 0 0 18px rgba(232,177,74,0.55)",
          }}
        />
      )}
      {/* 提示态光环 */}
      {hinted && !selected && (
        <motion.span
          className="absolute rounded-full"
          initial={{ opacity: 0.3, scale: 0.9 }}
          animate={{ opacity: [0.3, 0.7, 0.3], scale: [0.92, 1.08, 0.92] }}
          transition={{ duration: 1.2, repeat: Infinity, ease: "easeInOut" }}
          style={{
            width: size * 0.92,
            height: size * 0.92,
            boxShadow:
              "0 0 0 2px rgba(61,217,166,0.85), 0 0 16px rgba(61,217,166,0.5)",
          }}
        />
      )}
      {/* 宝石本体（带入场动画） */}
      <motion.div
        initial={{ scale: 0.4, y: -size * 0.4, opacity: 0 }}
        animate={{ scale: 1, y: 0, opacity: 1 }}
        transition={{ type: "spring", stiffness: 360, damping: 26 }}
        className="grid place-items-center"
        style={{ width: size, height: size }}
      >
        {partMode ? (
          <ToyPart color={cell.color} special={cell.special} size={size - 8} />
        ) : (
          <Gem color={cell.color} special={cell.special} size={size - 8} />
        )}
      </motion.div>
      {/* 清除中闪光 */}
      {clearing && (
        <motion.span
          className="pointer-events-none absolute inset-0 grid place-items-center"
          initial={{ opacity: 0, scale: 0.5 }}
          animate={{ opacity: [0, 1, 0], scale: [0.5, 1.5, 1.8] }}
          transition={{ duration: 0.32, ease: "easeOut" }}
        >
          <span
            className="rounded-full bg-white"
            style={{
              width: size * 0.5,
              height: size * 0.5,
              boxShadow:
                "0 0 24px rgba(255,255,255,0.95), 0 0 48px rgba(255,235,160,0.65)",
            }}
          />
        </motion.span>
      )}
    </motion.button>
  );
}
