import { useEffect, useState } from "react";

// 检测是否为触屏设备
function isTouchDevice(): boolean {
  return (
    typeof navigator !== "undefined" &&
    (navigator.maxTouchPoints > 0 || "ontouchstart" in window)
  );
}

// 根据窗口尺寸返回合适的宝石格大小
// 手机竖屏时自动交换宽高，模拟横屏视角
export function useCellSize(): number {
  const [size, setSize] = useState<number>(64);

  useEffect(() => {
    const compute = () => {
      let vw = window.innerWidth;
      let vh = window.innerHeight;

      // 触屏设备竖屏 → 交换宽高，让后续按横屏计算
      const touch = isTouchDevice();
      const portrait = vh > vw;
      const mobile = Math.min(vw, vh) < 768;
      if (touch && portrait && mobile) {
        [vw, vh] = [vh, vw];
      }

      const isLandscape = vw >= vh;
      // 横屏：侧栏在旁边；竖屏：侧栏在上下
      // 横屏需扣除：侧栏288 + 主容器padding48 + flex gap24 + 棋盘padding24 = 384
      // 竖屏需扣除：侧栏高度约280 + padding32

      if (isLandscape) {
        const maxByWidth = (vw - 384) / 8;
        const maxByHeight = (vh - 72) / 8;
        const raw = Math.floor(Math.min(maxByWidth, maxByHeight));
        setSize(Math.max(28, Math.min(52, raw)));
      } else {
        const maxByWidth = (vw - 32) / 8;
        const maxByHeight = (vh - 280) / 8;
        const raw = Math.floor(Math.min(maxByWidth, maxByHeight));
        setSize(Math.max(28, Math.min(44, raw)));
      }
    };
    compute();
    window.addEventListener("resize", compute);
    window.addEventListener("orientationchange", compute);
    return () => {
      window.removeEventListener("resize", compute);
      window.removeEventListener("orientationchange", compute);
    };
  }, []);

  return size;
}
