import type { GemColor, Special } from "@/game/types";

interface GemStyle {
  base: string;
  light: string;
  dark: string;
  glow: string;
  shape: string;
  // 圆角（shape 为 square 时使用）
  radius?: number;
}

const GEM_STYLES: Record<GemColor, GemStyle> = {
  ruby: {
    base: "#FF3B5C",
    light: "#FFB3C0",
    dark: "#8C1E32",
    glow: "rgba(255, 59, 92, 0.85)",
    shape: "polygon(50% 0%, 100% 50%, 50% 100%, 0% 50%)",
  },
  emerald: {
    base: "#3DD9A6",
    light: "#A6F0D5",
    dark: "#1E7A55",
    glow: "rgba(61, 217, 166, 0.85)",
    shape:
      "polygon(25% 4%, 75% 4%, 100% 50%, 75% 96%, 25% 96%, 0% 50%)",
  },
  sapphire: {
    base: "#3B7BFF",
    light: "#A8BCFF",
    dark: "#1E4396",
    glow: "rgba(59, 123, 255, 0.85)",
    shape: "circle",
  },
  topaz: {
    base: "#FFD23B",
    light: "#FFEDB0",
    dark: "#8C7414",
    glow: "rgba(255, 210, 59, 0.85)",
    shape: "polygon(50% 4%, 96% 92%, 4% 92%)",
  },
  amethyst: {
    base: "#A855F7",
    light: "#D7B6FB",
    dark: "#5A1E96",
    glow: "rgba(168, 85, 247, 0.85)",
    shape: "polygon(50% 0%, 100% 38%, 82% 100%, 18% 100%, 0% 38%)",
  },
  citrine: {
    base: "#FF7A1A",
    light: "#FFC299",
    dark: "#8C3E08",
    glow: "rgba(255, 122, 26, 0.85)",
    shape: "square",
    radius: 18,
  },
};

interface GemProps {
  color: GemColor;
  special: Special;
  size: number;
}

export default function Gem({ color, special, size }: GemProps) {
  const s = GEM_STYLES[color];

  // 彩虹覆盖原色
  const isRainbow = special === "rainbow";

  const background = isRainbow
    ? "conic-gradient(from 45deg, #FF3B5C, #FFD23B, #3DD9A6, #3B7BFF, #A855F7, #FF7A1A, #FF3B5C)"
    : `linear-gradient(140deg, ${s.light} 0%, ${s.base} 45%, ${s.dark} 100%)`;

  const boxShadow = isRainbow
    ? `0 0 22px rgba(255,255,255,0.55), inset 0 2px 4px rgba(255,255,255,0.7), inset 0 -6px 10px rgba(0,0,0,0.45)`
    : `0 0 14px ${s.glow}, inset 0 2px 4px rgba(255,255,255,0.55), inset 0 -8px 12px -2px rgba(0,0,0,0.45)`;

  const clipPath = s.shape === "circle" || s.shape === "square" ? "none" : s.shape;
  const borderRadius =
    s.shape === "circle" ? "50%" : s.shape === "square" ? `${s.radius ?? 18}px` : "0";

  return (
    <div
      className="relative grid place-items-center"
      style={{ width: size, height: size }}
    >
      {/* 主体 */}
      <div
        style={{
          width: size,
          height: size,
          background,
          boxShadow,
          clipPath: clipPath === "none" ? undefined : clipPath,
          borderRadius: clipPath === "none" ? borderRadius : undefined,
        }}
      />
      {/* 高光 */}
      <div
        className="pointer-events-none absolute"
        style={{
          width: size * 0.42,
          height: size * 0.42,
          top: size * 0.12,
          left: size * 0.14,
          background:
            "radial-gradient(circle at 35% 30%, rgba(255,255,255,0.85) 0%, rgba(255,255,255,0) 70%)",
          borderRadius: "50%",
          filter: "blur(1px)",
          opacity: 0.9,
        }}
      />
      {/* 特殊标记 */}
      {special !== "none" && (
        <SpecialMark special={special} size={size} color={s.light} />
      )}
    </div>
  );
}

function SpecialMark({
  special,
  size,
  color,
}: {
  special: Special;
  size: number;
  color: string;
}) {
  if (special === "rainbow") return null;
  const stroke = Math.max(2, Math.floor(size * 0.08));
  if (special === "line_h" || special === "line_v") {
    const isH = special === "line_h";
    return (
      <div
        className="pointer-events-none absolute"
        style={{
          width: isH ? size * 0.7 : stroke,
          height: isH ? stroke : size * 0.7,
          background: "rgba(255,255,255,0.95)",
          boxShadow: `0 0 8px ${color}, 0 0 4px rgba(255,255,255,0.8)`,
          borderRadius: 999,
          opacity: 0.95,
        }}
      />
    );
  }
  if (special === "bomb") {
    // 中心闪光点
    return (
      <div
        className="pointer-events-none absolute grid place-items-center"
        style={{ width: size, height: size }}
      >
        <div
          style={{
            width: size * 0.32,
            height: size * 0.32,
            background:
              "radial-gradient(circle, rgba(255,255,255,1) 0%, rgba(255,235,160,0.85) 40%, rgba(255,150,40,0) 75%)",
            borderRadius: "50%",
            boxShadow: "0 0 14px rgba(255,200,80,0.95)",
          }}
        />
      </div>
    );
  }
  if (special === "cross") {
    // 十字爆：水平 + 垂直交叉光条
    return (
      <div
        className="pointer-events-none absolute grid place-items-center"
        style={{ width: size, height: size }}
      >
        <div
          style={{
            width: size * 0.7,
            height: stroke,
            background: "rgba(255,255,255,0.95)",
            boxShadow: `0 0 8px ${color}, 0 0 4px rgba(255,255,255,0.8)`,
            borderRadius: 999,
            opacity: 0.95,
          }}
        />
        <div
          style={{
            position: "absolute",
            width: stroke,
            height: size * 0.7,
            background: "rgba(255,255,255,0.95)",
            boxShadow: `0 0 8px ${color}, 0 0 4px rgba(255,255,255,0.8)`,
            borderRadius: 999,
            opacity: 0.95,
          }}
        />
      </div>
    );
  }
  if (special === "nuke") {
    // 全屏脉冲光环
    return (
      <div
        className="pointer-events-none absolute grid place-items-center"
        style={{ width: size, height: size }}
      >
        <div
          style={{
            width: size * 0.5,
            height: size * 0.5,
            background:
              "radial-gradient(circle, rgba(255,255,255,1) 0%, rgba(168,85,247,0.9) 30%, rgba(59,123,255,0.6) 60%, transparent 80%)",
            borderRadius: "50%",
            boxShadow:
              "0 0 18px rgba(168,85,247,0.95), 0 0 28px rgba(59,123,255,0.6)",
          }}
        />
      </div>
    );
  }
  return null;
}
