import { motion } from "framer-motion";
import { Sparkles, Gem, Shirt, Crown, Plus, Zap } from "lucide-react";
import type { CardDef, Rarity } from "@/game/types";

interface CardViewProps {
  card: CardDef;
  // 是否已翻面（显示奖励）
  revealed: boolean;
  // 是否被玩家选中
  picked: boolean;
  // 是否禁用点击（已选了别的卡）
  disabled: boolean;
  onPick: () => void;
}

const RARITY_STYLE: Record<
  Rarity,
  { ring: string; glow: string; label: string; text: string }
> = {
  common: {
    ring: "rgba(191,183,155,0.5)",
    glow: "rgba(191,183,155,0.25)",
    label: "普通",
    text: "text-bone-300",
  },
  rare: {
    ring: "rgba(59,123,255,0.7)",
    glow: "rgba(59,123,255,0.35)",
    label: "稀有",
    text: "text-sapphire",
  },
  epic: {
    ring: "rgba(168,85,247,0.8)",
    glow: "rgba(168,85,247,0.45)",
    label: "史诗",
    text: "text-amethyst",
  },
};

function CardIcon({ kind, size = 22 }: { kind: CardDef["kind"]; size?: number }) {
  switch (kind) {
    case "score_next":
      return <Zap size={size} />;
    case "score_run":
      return <Sparkles size={size} />;
    case "score_now":
      return <Plus size={size} />;
    case "diamond":
      return <Gem size={size} />;
    case "cosmetic":
      return <Shirt size={size} />;
    default:
      return <Sparkles size={size} />;
  }
}

export default function CardView({
  card,
  revealed,
  picked,
  disabled,
  onPick,
}: CardViewProps) {
  const rarity = RARITY_STYLE[card.rarity];

  return (
    <motion.button
      type="button"
      onClick={() => !disabled && !revealed && onPick()}
      disabled={disabled || revealed}
      whileHover={!revealed && !disabled ? { y: -8 } : undefined}
      whileTap={!revealed && !disabled ? { scale: 0.96 } : undefined}
      className="relative"
      style={{ perspective: 1000 }}
      aria-label={revealed ? `卡牌 ${card.title}` : "未翻面卡牌"}
    >
      <motion.div
        className="relative h-64 w-44"
        animate={{ rotateY: revealed ? 180 : 0 }}
        transition={{ duration: 0.55, ease: "easeInOut" }}
        style={{ transformStyle: "preserve-3d" }}
      >
        {/* 正面（卡背） */}
        <div
          className="absolute inset-0 flex flex-col items-center justify-center gap-3 rounded-2xl"
          style={{
            backfaceVisibility: "hidden",
            background:
              "linear-gradient(135deg, rgba(168,85,247,0.25) 0%, rgba(232,177,74,0.18) 50%, rgba(20,20,40,0.7) 100%)",
            border: `1px solid ${rarity.ring}`,
            boxShadow: `0 12px 30px -10px ${rarity.glow}, 0 0 0 1px rgba(245,240,225,0.04) inset`,
          }}
        >
          <motion.div
            animate={{ rotate: [0, 8, -8, 0] }}
            transition={{ duration: 3, repeat: Infinity, ease: "easeInOut" }}
            className="grid h-16 w-16 place-items-center rounded-full"
            style={{
              background:
                "radial-gradient(circle, rgba(232,177,74,0.45) 0%, rgba(168,85,247,0.2) 70%, transparent 100%)",
            }}
          >
            <span className="font-display text-4xl font-black text-gradient-gold">
              ?
            </span>
          </motion.div>
          <p className="font-display text-[10px] uppercase tracking-[0.35em] text-bone-300/70">
            点击翻面
          </p>
          <span
            className={`absolute left-2 top-2 rounded-full px-2 py-0.5 text-[9px] uppercase tracking-widest ${rarity.text}`}
            style={{ background: "rgba(7,8,21,0.6)" }}
          >
            {rarity.label}
          </span>
        </div>

        {/* 背面（奖励） */}
        <div
          className="absolute inset-0 flex flex-col items-center justify-between gap-2 rounded-2xl p-4"
          style={{
            backfaceVisibility: "hidden",
            transform: "rotateY(180deg)",
            background:
              card.rarity === "epic"
                ? "linear-gradient(160deg, rgba(168,85,247,0.32) 0%, rgba(232,177,74,0.2) 55%, rgba(7,8,21,0.85) 100%)"
                : card.rarity === "rare"
                  ? "linear-gradient(160deg, rgba(59,123,255,0.3) 0%, rgba(232,177,74,0.16) 55%, rgba(7,8,21,0.85) 100%)"
                  : "linear-gradient(160deg, rgba(191,183,155,0.18) 0%, rgba(232,177,74,0.12) 55%, rgba(7,8,21,0.85) 100%)",
            border: `1px solid ${rarity.ring}`,
            boxShadow: `0 14px 36px -10px ${rarity.glow}`,
          }}
        >
          <span
            className={`self-start rounded-full px-2 py-0.5 text-[9px] uppercase tracking-widest ${rarity.text}`}
            style={{ background: "rgba(7,8,21,0.6)" }}
          >
            {rarity.label}
          </span>
          <motion.div
            initial={{ scale: 0.4, opacity: 0 }}
            animate={revealed ? { scale: 1, opacity: 1 } : { scale: 0.4, opacity: 0 }}
            transition={{ delay: 0.25, type: "spring", stiffness: 240, damping: 16 }}
            className="grid h-14 w-14 place-items-center rounded-full"
            style={{
              background:
                "radial-gradient(circle, rgba(232,177,74,0.4) 0%, transparent 70%)",
            }}
          >
            <span className="text-gradient-gold">
              <CardIcon kind={card.kind} />
            </span>
          </motion.div>
          <h4 className="font-display text-2xl font-bold text-bone-50">
            {card.title}
          </h4>
          <p className="text-center text-[11px] leading-snug text-bone-300/90">
            {card.desc}
          </p>
          <div className="flex items-center gap-1 text-gold-400">
            <Crown size={12} />
            <span className="text-[10px] uppercase tracking-widest">已生效</span>
          </div>
        </div>
      </motion.div>

      {/* 选中态外光环 */}
      {picked && (
        <motion.span
          className="pointer-events-none absolute -inset-1 rounded-2xl"
          initial={{ opacity: 0 }}
          animate={{ opacity: [0.5, 1, 0.5] }}
          transition={{ duration: 1.2, repeat: Infinity, ease: "easeInOut" }}
          style={{
            border: `2px solid ${rarity.ring}`,
            boxShadow: `0 0 24px ${rarity.glow}`,
          }}
        />
      )}
    </motion.button>
  );
}
