const RARITY_WEIGHT: Record<Rarity, number> = {
  common: 5,
  rare: 3,
  epic: 1,
};

function weightOf(card: CardDef): number {
  return RARITY_WEIGHT[card.rarity] ?? 1;
}

// 加权随机抽 3 张不重复卡牌
// allowBoosts=false 时过滤掉加成类卡（无下一关场景：失败或末关）
export function drawThreeCards(opts: { allowBoosts?: boolean } = {}): CardDef[] {
  const { allowBoosts = true } = opts;
  const pool = allowBoosts
    ? CARD_POOL
    : CARD_POOL.filter(
        (c) => c.kind !== "score_next" && c.kind !== "score_run",
      );
  const picked: CardDef[] = [];
  const used = new Set<string>();
  const available = pool.slice();
  while (picked.length < 3 && available.length > 0) {
    const totalWeight = available.reduce((s, c) => s + weightOf(c), 0);
    let r = Math.random() * totalWeight;
    let idx = 0;
    for (let i = 0; i < available.length; i++) {
      r -= weightOf(available[i]!);
      if (r <= 0) {
        idx = i;
        break;
      }
    }
    const card = available.splice(idx, 1)[0]!;
    if (!used.has(card.id)) {
      used.add(card.id);
      picked.push(card);
    }
  }
  return picked;
}
