// 宝石颜色（6 色）
export type GemColor =
  | "ruby"
  | "emerald"
  | "sapphire"
  | "topaz"
  | "amethyst"
  | "citrine";

export const GEM_COLORS: GemColor[] = [
  "ruby",
  "emerald",
  "sapphire",
  "topaz",
  "amethyst",
  "citrine",
];

// 特殊宝石类型
export type Special =
  | "none"
  | "line_h"
  | "line_v"
  | "bomb"
  | "rainbow"
  | "nuke"
  | "cross";

// 游戏模式
export type GameMode = "normal" | "ocean" | "rogue" | "pet" | "build" | "build2";

// Rogue 模式：卡牌奖励类型
// - score_next: 下一关分数加成（单次消耗）
// - score_run : 本 run 剩余关卡分数加成（可叠加）
// - score_now : 立即加分（可能把失败翻盘为胜利）
// - diamond   : 钻石货币（暂无实际作用）
// - cosmetic  : 限定装扮（暂无实际作用）
export type CardKind =
  | "score_next"
  | "score_run"
  | "score_now"
  | "diamond"
  | "cosmetic";

export type Rarity = "common" | "rare" | "epic";

export interface CardDef {
  id: string;
  kind: CardKind;
  title: string;
  desc: string;
  rarity: Rarity;
  // score_next/score_run: 分数加成比例（0.3 = +30%）
  // score_now: 直接加分数
  // diamond: 钻石数量
  // cosmetic: 占位 0
  value: number;
  // 仅 cosmetic 用
  cosmeticId?: string;
}

// 棋盘单元格（null 表示空位，下落补充阶段会使用）
export interface Cell {
  id: string;
  color: GemColor;
  special: Special;
  // 海洋模式：是否附带泳圈（带泳圈的棋子在三消时优先破坏泳圈而非棋子）
  floater?: boolean;
}

// 爱宠大机密模式：宠物种类
export type PetKind = "cat" | "rabbit" | "dog";

// 爱宠大机密模式：玩具所需的某种零件（color 复用 GemColor，每色对应一种零件）
export interface ToyPartRequirement {
  color: GemColor;
  count: number;
}

// 爱宠大机密模式：玩具定义（宠物想要的目标）
export interface Toy {
  id: string;
  name: string; // "毛线球"
  emoji: string; // "🧶" 气泡中展示
  parts: ToyPartRequirement[];
}

// 爱宠大机密模式：关卡配置（无 targetScore；分数仅展示）
export interface PetLevelConfig {
  id: number;
  moves: number;
  pet: PetKind;
  toy1: Toy; // 阶段1玩具（4-6 零件）
  toy2: Toy; // 阶段2玩具（5-10 零件）
  mechanic: string;
  mode?: "pet";
}

// 构筑模式：buff 等级（0=未解锁, 1=tier1, 2=tier2）
export type BuffTier = 0 | 1 | 2;

// 构筑模式：单色 buff 配置
export interface BuildBuffConfig {
  color: GemColor;
  partName: string;
  partEmoji: string;
  n: number; // tier1 阈值
  m: number; // tier2 阈值
  nameT1: string;
  nameT2: string;
  descT1: string;
  descT2: string;
}

// 构筑模式：整体配置
export interface BuildConfig {
  timer: number; // 倒计时秒数
  buffs: BuildBuffConfig[]; // 6 项
}

export type Grid = (Cell | null)[][];

// 关卡配置
export interface LevelConfig {
  id: number;
  targetScore: number;
  moves: number;
  // 该关启用何种机制介绍（仅 UI 提示文案，不影响逻辑）
  mechanic: string;
  mode?: GameMode;
  // 海洋模式：初始水位（水面行索引，0=水面在顶部即棋盘全淹没，ROWS=棋盘全浮出）
  waterStart?: number;
}

// 持久化进度
export interface LevelRecord {
  stars: number;
  bestScore: number;
}
export interface Progress {
  unlockedLevel: number;
  totalScore: number;
  bestCombo: number;
  records: Record<number, LevelRecord>;
  // 海洋模式独立进度
  oceanUnlocked: number;
  oceanRecords: Record<number, LevelRecord>;
  // Rogue 模式：钻石货币（暂无实际作用）
  diamonds: number;
  // Rogue 模式：已解锁装扮 id 列表（暂无实际作用）
  cosmetics: string[];
  // 爱宠大机密模式：已解锁关卡
  petUnlocked: number;
  // 爱宠大机密模式：关卡记录
  petRecords: Record<number, LevelRecord>;
  // 构筑模式：各时长最高分（key = 秒数）
  buildBestScores: Record<number, number>;
  // 构筑V2模式：各时长最高分
  build2BestScores: Record<number, number>;
}

// 一次消除事件（用于动画与得分明细）
export interface ClearEvent {
  cells: { row: number; col: number }[];
  color: GemColor | "mixed";
  special?: Special;
  // 触发的特殊宝石坐标（如有）
  triggeredBy?: { row: number; col: number };
  // 该次消除的连击序号（0 起步）
  cascadeIndex: number;
}

// 形状识别结果（决定特殊宝石）
interface ShapeResult {
  // 应在何处放置特殊宝石（匹配区域中点）
  pivot: { row: number; col: number };
  special: Special;
}

let idCounter = 0;
export function newId(): string {
  idCounter += 1;
  return `g${idCounter}_${Math.random().toString(36).slice(2, 7)}`;
}

export function makeCell(
  color: GemColor,
  special: Special = "none",
  floater = false,
): Cell {
  return { id: newId(), color, special, floater };
}

export function randomColor(): GemColor {
  return GEM_COLORS[Math.floor(Math.random() * GEM_COLORS.length)]!;
}

export type Shape = ShapeResult;
