import { motion } from "framer-motion";
import { ArrowLeft, Dices, Gem, Sparkles, Crown, Shirt } from "lucide-react";
import { LEVELS } from "@/game/levels";
import { useGame } from "@/hooks/useGame";

interface RogueHubProps {
  onStartRun: () => void;
}

const RULES: { icon: React.ReactNode; title: string; desc: string }[] = [
  {
    icon: <Dices size={16} className="text-gold-400" />,
    title: "一局一抽奖",
    desc: "每完成一关（胜负皆可）结算后随机生成 3 张卡牌，选 1 张翻面生效。",
  },
  {
    icon: <Sparkles size={16} className="text-gold-400" />,
    title: "加成塑造 run",
    desc: "「下一关加成」单次生效；「全程加成」可叠加，覆盖剩余所有关卡。",
  },
  {
    icon: <Crown size={16} className="text-gold-400" />,
    title: "翻盘可能",
    desc: "「立即加分」卡可能把失败翻盘为胜利，救回一命。",
  },
  {
    icon: <Gem size={16} className="text-gold-400" />,
    title: "钻石与装扮",
    desc: "收集钻石与限定装扮（暂未启用实际用途，敬请期待）。",
  },
];

export default function RogueHub({ onStartRun }: RogueHubProps) {
  const progress = useGame((s) => s.progress);
  const goToHub = useGame((s) => s.goToHub);
  const bestCombo = progress.bestCombo;

  return (
    <div className="relative mx-auto flex w-full max-w-6xl flex-col gap-8 px-6 py-10">
      {/* 返回 */}
      <motion.button
        type="button"
        onClick={goToHub}
        initial={{ opacity: 0, x: -8 }}
        animate={{ opacity: 1, x: 0 }}
        transition={{ duration: 0.4 }}
        className="flex items-center gap-2 self-start text-sm text-bone-300/80 transition hover:text-gold-400"
      >
        <ArrowLeft size={16} />
        返回主界面
      </motion.button>

      {/* Hero */}
      <motion.header
        initial={{ opacity: 0, y: 16 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.7, ease: "easeOut" }}
        className="flex flex-col items-center gap-3 pt-2 text-center"
      >
        <motion.div
          initial={{ letterSpacing: "0.6em", opacity: 0 }}
          animate={{ letterSpacing: "0.18em", opacity: 1 }}
          transition={{ duration: 1.1, ease: "easeOut" }}
          className="flex items-center gap-4"
        >
          <motion.span
            animate={{ rotate: [0, -10, 10, 0] }}
            transition={{ duration: 4, repeat: Infinity, ease: "easeInOut" }}
          >
            <Dices size={36} className="text-gold-400" />
          </motion.span>
          <h1 className="font-display text-5xl font-black tracking-[0.18em] text-bone-50 sm:text-6xl">
            荣光
          </h1>
        </motion.div>
        <p className="font-display text-2xl italic tracking-[0.3em] text-gradient-gold sm:text-3xl">
          Rogue Run
        </p>
        <p className="mt-1 max-w-md text-sm text-bone-300/80">
          连闯 10 关 · 每关结算抽卡 · 用卡牌加成堆叠你的征途
        </p>
      </motion.header>

      {/* 状态面板 */}
      <motion.section
        initial={{ opacity: 0, y: 12 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.6, delay: 0.25 }}
        className="grid grid-cols-1 gap-4 sm:grid-cols-3"
      >
        <StatCard
          icon={<Gem size={16} className="text-gold-400" />}
          label="钻石"
          value={progress.diamonds.toLocaleString()}
        />
        <StatCard
          icon={<Shirt size={16} className="text-gold-400" />}
          label="限定装扮"
          value={`${progress.cosmetics.length}`}
        />
        <StatCard
          icon={<Crown size={16} className="text-gold-400" />}
          label="最高连击"
          value={`×${bestCombo + 1}`}
        />
      </motion.section>

      {/* 规则 */}
      <motion.section
        initial={{ opacity: 0, y: 12 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.6, delay: 0.35 }}
        className="glass rounded-2xl p-5"
      >
        <h3 className="mb-3 font-display text-sm font-semibold uppercase tracking-[0.3em] text-bone-100">
          规则
        </h3>
        <div className="grid grid-cols-1 gap-3 sm:grid-cols-2">
          {RULES.map((r, i) => (
            <div key={i} className="flex items-start gap-3">
              <span className="mt-0.5 grid h-7 w-7 shrink-0 place-items-center rounded-lg bg-ink-900/60">
                {r.icon}
              </span>
              <div>
                <p className="text-sm font-semibold text-bone-100">{r.title}</p>
                <p className="text-[11px] leading-snug text-bone-300/80">
                  {r.desc}
                </p>
              </div>
            </div>
          ))}
        </div>
      </motion.section>

      {/* 关卡预览 */}
      <motion.section
        initial={{ opacity: 0, y: 12 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.6, delay: 0.4 }}
        className="glass rounded-2xl p-5"
      >
        <h3 className="mb-3 font-display text-sm font-semibold uppercase tracking-[0.3em] text-bone-100">
          征途关卡（{LEVELS.length} 关）
        </h3>
        <div className="flex flex-wrap gap-2">
          {LEVELS.map((l) => (
            <span
              key={l.id}
              className="rounded-lg bg-ink-900/60 px-3 py-1.5 text-xs text-bone-300/85"
            >
              <span className="font-display text-gold-400">L{l.id}</span>{" "}
              {l.mechanic}
            </span>
          ))}
        </div>
      </motion.section>

      {/* 开始按钮 */}
      <motion.div
        initial={{ opacity: 0, y: 12 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.6, delay: 0.45 }}
        className="flex justify-center pb-6"
      >
        <motion.button
          type="button"
          onClick={onStartRun}
          whileHover={{ y: -3 }}
          whileTap={{ scale: 0.97 }}
          className="flex items-center gap-3 rounded-2xl bg-gold-500 px-10 py-4 font-display text-lg font-bold uppercase tracking-[0.3em] text-ink-900 shadow-gold transition hover:bg-gold-400"
        >
          <Dices size={22} />
          开启 run
        </motion.button>
      </motion.div>
    </div>
  );
}

function StatCard({
  icon,
  label,
  value,
}: {
  icon: React.ReactNode;
  label: string;
  value: string;
}) {
  return (
    <div className="glass flex items-center gap-3 rounded-2xl p-4">
      <span className="grid h-9 w-9 place-items-center rounded-xl bg-ink-900/60">
        {icon}
      </span>
      <div>
        <p className="text-[10px] uppercase tracking-[0.25em] text-bone-300/70">
          {label}
        </p>
        <p className="font-display text-xl font-bold text-bone-50">{value}</p>
      </div>
    </div>
  );
}
