import { motion } from "framer-motion";
import { Wrench, Timer, Zap, TrendingUp, Sparkles, Bomb, Atom, Clock } from "lucide-react";
import { BUILD_CONFIG, BUILD_TIME_OPTIONS } from "@/game/levels";
import { useGame } from "@/hooks/useGame";

interface BuildHubProps {
  onStart: (duration: number) => void;
  mode?: "build" | "build2";
}

export default function BuildHub({ onStart, mode = "build" }: BuildHubProps) {
  const isBuild2 = mode === "build2";
  const buildBestScores = useGame((s) =>
    isBuild2 ? s.progress.build2BestScores : s.progress.buildBestScores,
  );
  const goToHub = useGame((s) => s.goToHub);

  const buffIcons = [
    { icon: Clock, color: "text-ruby-300" },
    { icon: TrendingUp, color: "text-emerald-300" },
    { icon: Sparkles, color: "text-topaz-300" },
    { icon: Zap, color: "text-sapphire-300" },
    { icon: Atom, color: "text-amethyst-300" },
    { icon: Bomb, color: "text-citrine-300" },
  ];

  return (
    <div className="mx-auto max-w-3xl px-4 py-8 sm:py-12">
      {/* 返回 */}
      <button
        onClick={goToHub}
        className="mb-6 text-sm text-bone-300/70 transition hover:text-bone-100"
      >
        ← 返回主界面
      </button>

      {/* Hero */}
      <motion.div
        initial={{ opacity: 0, y: 12 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.5 }}
        className="text-center"
      >
        <motion.div
          animate={{ rotate: [0, 180, 360] }}
          transition={{ rotate: { duration: 8, repeat: Infinity, ease: "linear" } }}
          className="mx-auto mb-4 grid h-16 w-16 place-items-center rounded-2xl"
          style={{
            background:
              "radial-gradient(circle, rgba(61,217,166,0.35) 0%, rgba(59,123,255,0.2) 70%, transparent 100%)",
            boxShadow: "0 0 30px rgba(61,217,166,0.3) inset",
          }}
        >
          <Wrench size={32} className="text-emerald-300" />
        </motion.div>
        <h1 className="font-display text-4xl font-bold text-bone-50 sm:text-5xl">
          {isBuild2 ? "构筑 V2" : "构筑"}
        </h1>
        <p className="mt-2 text-sm text-emerald-300/70">
          {isBuild2
            ? "Build V2 · 仅玩家主动消除计入 buff 激活"
            : "Build · 无尽 buff 协同挑战"}
        </p>
        <p className="mx-auto mt-3 max-w-md text-sm text-bone-300/80">
          {isBuild2
            ? "只有通过玩家移动棋子消除的棋子才计入 buff 激活计数。buff 效果和系统生成的棋子完成的非玩家消除不计入。更讲究策略的构筑挑战。"
            : "消除棋子积累零件计数，达成阈值解锁 buff。6 种 buff 永久生效、互相协同，在有限时间内构筑最强组合。"}
        </p>
      </motion.div>

      {/* 时长选择 + 最高分 */}
      <motion.div
        initial={{ opacity: 0, y: 12 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.5, delay: 0.1 }}
        className="mt-8"
      >
        <h2 className="mb-3 text-center font-display text-sm uppercase tracking-[0.3em] text-emerald-300/60">
          选择挑战时长
        </h2>
        <div className="grid grid-cols-1 gap-3 sm:grid-cols-3">
          {BUILD_TIME_OPTIONS.map((duration) => {
            const best = buildBestScores[duration] ?? 0;
            return (
              <button
                key={duration}
                onClick={() => onStart(duration)}
                className="group relative overflow-hidden rounded-xl p-4 text-center transition"
                style={{
                  background:
                    "linear-gradient(120deg, rgba(61,217,166,0.18) 0%, rgba(59,123,255,0.12) 100%)",
                  border: "1px solid rgba(61,217,166,0.3)",
                }}
              >
                <div className="pointer-events-none absolute inset-0 opacity-0 transition group-hover:opacity-100"
                  style={{
                    background:
                      "linear-gradient(120deg, rgba(61,217,166,0.18) 0%, rgba(59,123,255,0.12) 100%)",
                  }}
                />
                <div className="relative z-10">
                  <div className="mb-1 flex items-center justify-center gap-1 text-emerald-300/80">
                    <Timer size={14} />
                    <span className="font-display text-2xl font-bold text-bone-50">
                      {duration}
                    </span>
                    <span className="text-xs text-bone-300/60">秒</span>
                  </div>
                  <p className="font-display text-[10px] uppercase tracking-[0.2em] text-emerald-300/60">
                    最高分
                  </p>
                  <p className="font-display text-sm font-bold text-emerald-200">
                    {best.toLocaleString()}
                  </p>
                  <p className="mt-2 font-display text-xs font-bold text-emerald-50/80 transition group-hover:text-emerald-50">
                    开始 {duration}s
                  </p>
                </div>
              </button>
            );
          })}
        </div>
      </motion.div>

      {/* Buff 图鉴 */}
      <motion.div
        initial={{ opacity: 0, y: 12 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.5, delay: 0.2 }}
        className="mt-10"
      >
        <h2 className="mb-4 text-center font-display text-sm uppercase tracking-[0.3em] text-emerald-300/60">
          Buff 图鉴
        </h2>
        <div className="grid gap-2 sm:grid-cols-2">
          {BUILD_CONFIG.buffs.map((cfg, i) => {
            const Icon = buffIcons[i]!.icon;
            return (
              <div
                key={cfg.color}
                className="glass flex items-start gap-3 rounded-xl p-3"
              >
                <div className="mt-0.5 grid h-9 w-9 flex-shrink-0 place-items-center rounded-lg bg-white/5">
                  <Icon size={18} className={buffIcons[i]!.color} />
                </div>
                <div className="flex-1 min-w-0">
                  <div className="flex items-baseline gap-2">
                    <span className="text-base">{cfg.partEmoji}</span>
                    <p className="text-sm font-bold text-bone-100">
                      {cfg.nameT1}
                    </p>
                    <span className="text-[10px] text-bone-400/50">
                      {cfg.n} → {cfg.m}
                    </span>
                  </div>
                  <p className="mt-0.5 text-[11px] leading-tight text-bone-300/70">
                    {cfg.descT1}
                  </p>
                  <p className="mt-1 text-[11px] leading-tight text-emerald-300/60">
                    II: {cfg.descT2}
                  </p>
                </div>
              </div>
            );
          })}
        </div>
      </motion.div>

      {/* 规则提示 */}
      <motion.div
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        transition={{ duration: 0.5, delay: 0.3 }}
        className="mt-8 rounded-xl border border-emerald-500/15 bg-emerald-500/5 p-4 text-center"
      >
        <p className="text-xs text-bone-300/70">
          <Timer size={14} className="mr-1 inline text-emerald-300/60" />
          三档倒计时：{BUILD_TIME_OPTIONS.join(" / ")} 秒 · 各档独立排行榜 · 无步数限制
        </p>
        <p className="mt-1 text-xs text-bone-300/50">
          消除同色棋子越多 → 越快解锁对应 buff → 多 buff 叠加产生 1+1＞2 的协同效果
        </p>
      </motion.div>
    </div>
  );
}
