import { motion, AnimatePresence } from "framer-motion";
import { GEM_COLORS, type GemColor } from "@/game/types";
import { PET_PART_INFO } from "@/game/levels";
import { useGame } from "@/hooks/useGame";

// 爱宠大机密模式：底部 6 种零件持有量栏
// - 显示每种零件 emoji + 当前持有数 / 当前阶段需求数
// - 当前阶段所需色高亮
// - 已完成的需求标绿
export default function PartsBar() {
  const mode = useGame((s) => s.mode);
  const toys = useGame((s) => s.petToys);
  const stage = useGame((s) => s.petToyStage);
  const collected = useGame((s) => s.petPartsCollected);
  const phase = useGame((s) => s.phase);

  if (mode !== "pet" || !toys) return null;

  // 当前阶段玩具
  const currentToy = stage === 1 ? toys.stage1 : toys.stage2;
  // 当前阶段需求映射：color → count
  const reqMap = new Map<GemColor, number>();
  for (const p of currentToy.parts) reqMap.set(p.color, p.count);

  // 全局已结束（胜负判定）时仍显示最终状态
  const settled = phase === "ended";

  return (
    <div
      className="glass rounded-2xl p-3"
      style={{
        background:
          "linear-gradient(180deg, rgba(255,210,160,0.10), rgba(168,85,247,0.05))",
        border: "1px solid rgba(255,200,140,0.18)",
      }}
    >
      <div className="mb-2 flex items-center justify-between">
        <div className="flex items-center gap-2">
          <span className="font-display text-[11px] uppercase tracking-[0.25em] text-bone-300/80">
            零件收集
          </span>
          <span className="text-xs text-bone-300/60">
            阶段 <span className="text-gold-400">{stage}</span> / 2
          </span>
        </div>
        <span className="text-xs text-bone-300/60">
          目标：<span className="text-bone-100">{currentToy.name}</span>{" "}
          <span className="text-base leading-none">{currentToy.emoji}</span>
        </span>
      </div>

      <div className="grid grid-cols-6 gap-2">
        {GEM_COLORS.map((color) => {
          const info = PET_PART_INFO[color];
          const have = collected[color] ?? 0;
          const need = reqMap.get(color);
          const isRequired = need !== undefined;
          const isDone = isRequired && have >= (need ?? 0);
          // 高亮：当前阶段需要的色
          const highlight = isRequired && !isDone;
          const dim = !isRequired;

          return (
            <motion.div
              key={color}
              initial={false}
              animate={{
                scale: isDone ? 1 : 0.98,
              }}
              className="flex flex-col items-center gap-1 rounded-xl px-1 py-2"
              style={{
                background: isDone
                  ? "rgba(61,217,166,0.16)"
                  : highlight
                    ? "rgba(232,177,74,0.14)"
                    : "rgba(255,255,255,0.03)",
                border: `1px solid ${
                  isDone
                    ? "rgba(61,217,166,0.5)"
                    : highlight
                      ? "rgba(232,177,74,0.45)"
                      : "rgba(255,255,255,0.06)"
                }`,
                opacity: dim ? 0.55 : 1,
                transition: "all 0.25s ease",
              }}
            >
              <span
                className="select-none"
                style={{
                  fontSize: 18,
                  lineHeight: 1,
                  filter: isDone
                    ? "drop-shadow(0 0 6px rgba(61,217,166,0.7))"
                    : "none",
                }}
              >
                {info.emoji}
              </span>
              <span className="font-display text-[10px] text-bone-300/70">
                {info.name}
              </span>
              <AnimatePresence mode="popLayout" initial={false}>
                <motion.div
                  key={`${have}-${need ?? "x"}`}
                  initial={{ scale: 1.3, opacity: 0.4 }}
                  animate={{ scale: 1, opacity: 1 }}
                  transition={{ duration: 0.25 }}
                  className="font-display text-sm font-bold"
                  style={{
                    color: isDone
                      ? "#3DD9A6"
                      : highlight
                        ? "#F2C75E"
                        : "#F5F0E1",
                  }}
                >
                  {have}
                  {isRequired ? (
                    <span className="text-bone-300/50">/{need}</span>
                  ) : null}
                </motion.div>
              </AnimatePresence>
              {/* 状态标签 */}
              <div className="h-3 text-[9px] leading-3">
                {isDone ? (
                  <span className="text-emerald">✓ 完成</span>
                ) : isRequired ? (
                  <span className="text-gold-400/80">需求</span>
                ) : (
                  <span className="text-bone-300/40">—</span>
                )}
              </div>
            </motion.div>
          );
        })}
      </div>

      {/* 结算提示 */}
      {settled && (
        <p className="mt-2 text-center text-[11px] text-bone-300/60">
          本局结算 · 零件不再累加
        </p>
      )}
    </div>
  );
}
