import { motion, AnimatePresence } from "framer-motion";
import { useGame } from "@/hooks/useGame";
import { BUILD_CONFIG } from "@/game/levels";
import type { GemColor, BuffTier } from "@/game/types";

// 构筑模式左侧面板：6 色 buff 列表 + 倒计时
export default function BuildPanel() {
  const buildTimer = useGame((s) => s.buildTimer);
  const buildClearCounts = useGame((s) => s.buildClearCounts);
  const buildBuffs = useGame((s) => s.buildBuffs);
  const buildScoreMult = useGame((s) => s.buildScoreMult);
  const buildTimeBonus = useGame((s) => s.buildTimeBonus);
  const buildFlashKey = useGame((s) => s.buildFlashKey);

  const mm = Math.floor(buildTimer / 60);
  const ss = buildTimer % 60;
  const timeStr = `${String(mm).padStart(2, "0")}:${String(ss).padStart(2, "0")}`;
  const isUrgent = buildTimer <= 10 && buildTimer > 0;

  const activeCount = Object.values(buildBuffs).filter((t) => t > 0).length;

  return (
    <div className="glass flex flex-col gap-3 rounded-2xl p-4">
      {/* 倒计时 */}
      <div className="text-center">
        <p className="font-display text-[10px] uppercase tracking-[0.3em] text-emerald-300/70">
          剩余时间
        </p>
        <motion.p
          animate={
            isUrgent
              ? { color: ["#FF6B8A", "#FFD23B", "#FF6B8A"], scale: [1, 1.08, 1] }
              : { color: "#E8F4D9", scale: 1 }
          }
          transition={
            isUrgent
              ? { duration: 0.6, repeat: Infinity, ease: "easeInOut" }
              : { duration: 0.3 }
          }
          className="font-display text-4xl font-bold tabular-nums"
        >
          {timeStr}
        </motion.p>
      </div>

      {/* 摘要 */}
      <div className="flex justify-between gap-2 text-[11px]">
        <div className="flex-1 rounded-lg bg-emerald-500/10 px-2 py-1.5 text-center">
          <p className="text-emerald-300/60">激活 buff</p>
          <p className="font-bold text-emerald-200">{activeCount} / 6</p>
        </div>
        <div className="flex-1 rounded-lg bg-sapphire-500/10 px-2 py-1.5 text-center">
          <p className="text-sapphire-300/60">分数乘数</p>
          <p className="font-bold text-sapphire-200">×{buildScoreMult.toFixed(1)}</p>
        </div>
        <div className="flex-1 rounded-lg bg-ruby-500/10 px-2 py-1.5 text-center">
          <p className="text-ruby-300/60">时间加成</p>
          <p className="font-bold text-ruby-200">+{buildTimeBonus}s</p>
        </div>
      </div>

      {/* 6 色 buff 列表 */}
      <div className="flex flex-col gap-1.5">
        {BUILD_CONFIG.buffs.map((cfg) => (
          <BuffRow
            key={cfg.color}
            color={cfg.color}
            cfg={cfg}
            count={buildClearCounts[cfg.color]}
            tier={buildBuffs[cfg.color]}
            flashKey={buildFlashKey[cfg.color] ?? 0}
          />
        ))}
      </div>
    </div>
  );
}

function BuffRow({
  color,
  cfg,
  count,
  tier,
  flashKey,
}: {
  color: GemColor;
  cfg: (typeof BUILD_CONFIG.buffs)[number];
  count: number;
  tier: BuffTier;
  flashKey: number;
}) {
  const target = tier === 0 ? cfg.n : tier === 1 ? cfg.m : cfg.m;
  const isMax = tier === 2;
  const isActive = tier > 0;
  const progress = Math.min(count / target, 1);

  const borderColor = isActive
    ? color === "ruby"
      ? "rgba(255,59,92,0.5)"
      : color === "emerald"
        ? "rgba(61,217,166,0.5)"
        : color === "sapphire"
          ? "rgba(59,123,255,0.5)"
          : color === "topaz"
            ? "rgba(255,210,59,0.5)"
            : color === "amethyst"
              ? "rgba(168,85,247,0.5)"
              : "rgba(255,122,26,0.5)"
    : "rgba(255,255,255,0.08)";

  const bgColor = isActive
    ? color === "ruby"
      ? "rgba(255,59,92,0.08)"
      : color === "emerald"
        ? "rgba(61,217,166,0.08)"
        : color === "sapphire"
          ? "rgba(59,123,255,0.08)"
          : color === "topaz"
            ? "rgba(255,210,59,0.08)"
            : color === "amethyst"
              ? "rgba(168,85,247,0.08)"
              : "rgba(255,122,26,0.08)"
    : "transparent";

  return (
    <motion.div
      animate={
        isActive
          ? { boxShadow: `0 0 12px ${borderColor}` }
          : { boxShadow: "0 0 0px transparent" }
      }
      transition={{ duration: 0.3 }}
      className="relative overflow-hidden rounded-lg border px-2.5 py-1.5"
      style={{
        borderColor,
        background: bgColor,
      }}
    >
      {/* buff 触发闪光特效 */}
      {flashKey > 0 && (
        <motion.div
          key={flashKey}
          initial={{ opacity: 0.7, scale: 1.08 }}
          animate={{ opacity: 0, scale: 1 }}
          transition={{ duration: 0.5, ease: "easeOut" }}
          className="pointer-events-none absolute inset-0 rounded-lg"
          style={{
            background: borderColor.replace(/0\.\d+/, "0.35"),
            boxShadow: `0 0 24px ${borderColor}, inset 0 0 16px ${borderColor}`,
          }}
        />
      )}
      <div className="relative z-10 flex items-center gap-2">
        {/* 零件图标 */}
        <span className="text-lg">{cfg.partEmoji}</span>
        {/* 名称 + 计数 */}
        <div className="flex-1 min-w-0">
          <div className="flex items-baseline justify-between">
            <p className={`text-xs font-bold ${isActive ? "text-bone-50" : "text-bone-300/60"}`}>
              {cfg.partName}
            </p>
            <p className={`text-xs font-bold tabular-nums ${isActive ? "text-bone-100" : "text-bone-400/50"}`}>
              {count} / {target}
            </p>
          </div>
          {/* 进度条 */}
          <div className="mt-0.5 h-1 overflow-hidden rounded-full bg-white/8">
            <motion.div
              animate={{ width: `${progress * 100}%` }}
              transition={{ duration: 0.4 }}
              className="h-full rounded-full"
              style={{
                background: isActive
                  ? borderColor.replace("0.5", "0.8")
                  : "rgba(255,255,255,0.2)",
              }}
            />
          </div>
        </div>
        {/* buff 标签 */}
        <div className="flex-shrink-0">
          <AnimatePresence mode="wait">
            {tier === 0 ? (
              <motion.span
                key="locked"
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                exit={{ opacity: 0 }}
                className="text-[9px] uppercase tracking-wider text-bone-400/40"
              >
                锁定
              </motion.span>
            ) : (
              <motion.span
                key="active"
                initial={{ opacity: 0, scale: 0.8 }}
                animate={{ opacity: 1, scale: 1 }}
                exit={{ opacity: 0, scale: 0.8 }}
                className={`rounded px-1.5 py-0.5 text-[9px] font-bold uppercase tracking-wider ${
                  isMax
                    ? "bg-amber-400/20 text-amber-200"
                    : "bg-emerald-400/20 text-emerald-200"
                }`}
              >
                {isMax ? "II" : "I"}
              </motion.span>
            )}
          </AnimatePresence>
        </div>
      </div>
      {/* buff 描述（始终显示） */}
      <div className="relative z-10 mt-1 space-y-0.5">
        <p
          className={`text-[10px] leading-tight ${
            tier >= 1
              ? "text-emerald-200/80"
              : "text-bone-400/45"
          }`}
        >
          I: {cfg.descT1}
        </p>
        <p
          className={`text-[10px] leading-tight ${
            tier >= 2
              ? "text-amber-200/80"
              : "text-bone-400/45"
          }`}
        >
          II: {cfg.descT2}
        </p>
      </div>
    </motion.div>
  );
}
