// 星级评定：基于目标分倍率
export function starsForScore(score: number, target: number): number {
  if (score >= target * 1.6) return 3;
  if (score >= target * 1.25) return 2;
  if (score >= target) return 1;
  return 0;
}

// 海洋模式：根据得分进度计算当前水位（行索引）
// score 进度从 0 到 target，水位从 waterStart 线性增长到 ROWS（全浮出）
export function waterLevelForScore(
  score: number,
  target: number,
  waterStart: number,
): number {
  const ratio = Math.min(1, Math.max(0, score / target));
  const end = ROWS; // 全浮出
  return Math.round(waterStart + (end - waterStart) * ratio);
}

