function StatCard({
  icon,
  label,
  value,
}: {
  icon: React.ReactNode;
  label: string;
  value: string;
}) {
  return (
    <div className="glass flex items-center gap-3 rounded-2xl p-4">
      <div className="grid h-9 w-9 place-items-center rounded-lg bg-ink-700/60">
        {icon}
      </div>
      <div>
        <p className="font-display text-[10px] uppercase tracking-[0.25em] text-bone-300/70">
          {label}
        </p>
        <p className="font-display text-2xl font-bold leading-none text-bone-50">
          {value}
        </p>
      </div>
    </div>
  );
}
