import { motion, AnimatePresence } from "framer-motion";
import { useGame } from "@/hooks/useGame";
import { PET_AVATAR, getPetLevel } from "@/game/levels";
import type { Toy } from "@/game/types";

// 爱宠大机密模式：右侧宠物面板
// - 宠物头像（浮动动画）
// - 头顶玩具气泡（当前阶段目标）
// - 阶段进度（1/2，阶段1完成提示切换）
export default function PetPanel() {
  const mode = useGame((s) => s.mode);
  const petKind = useGame((s) => s.petKind);
  const toys = useGame((s) => s.petToys);
  const stage = useGame((s) => s.petToyStage);
  const petPhase = useGame((s) => s.petPhase);
  const levelId = useGame((s) => s.currentLevelId);
  const phase = useGame((s) => s.phase);

  if (mode !== "pet" || !petKind || !toys) return null;

  const avatar = PET_AVATAR[petKind];
  const currentToy: Toy = stage === 1 ? toys.stage1 : toys.stage2;
  const petName =
    petKind === "cat" ? "小猫" : petKind === "rabbit" ? "小兔" : "小狗";
  const level = getPetLevel(levelId);
  const settled = phase === "ended";

  // 阶段1刚完成、准备切换到阶段2
  const switching = petPhase === "stage1Done";

  return (
    <div
      className="glass relative flex flex-col items-center gap-3 rounded-2xl p-4"
      style={{
        background:
          "linear-gradient(180deg, rgba(255,210,160,0.12), rgba(168,85,247,0.06))",
        border: "1px solid rgba(255,200,140,0.22)",
      }}
    >
      {/* 标题 */}
      <div className="flex w-full items-center justify-between">
        <span className="font-display text-[11px] uppercase tracking-[0.25em] text-bone-300/80">
          爱宠
        </span>
        <span className="font-display text-xs text-bone-300/60">
          {petName}
        </span>
      </div>

      {/* 玩具气泡 + 宠物头像 */}
      <div className="relative flex flex-col items-center">
        {/* 头顶气泡：当前想要的玩具 */}
        <AnimatePresence mode="wait">
          <motion.div
            key={currentToy.id + (switching ? "-sw" : "")}
            initial={{ opacity: 0, y: 8, scale: 0.8 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: -8, scale: 0.8 }}
            transition={{ duration: 0.35 }}
            className="relative mb-2 rounded-2xl px-4 py-2 text-center"
            style={{
              background:
                "linear-gradient(180deg, rgba(255,255,255,0.95), rgba(245,240,225,0.85))",
              boxShadow:
                "0 6px 20px -6px rgba(0,0,0,0.4), inset 0 1px 0 rgba(255,255,255,0.9)",
            }}
          >
            {/* 气泡尖角 */}
            <div
              className="absolute left-1/2 -bottom-1 h-3 w-3 -translate-x-1/2 rotate-45"
              style={{
                background: "rgba(245,240,225,0.95)",
                boxShadow: "1px 1px 2px rgba(0,0,0,0.1)",
              }}
            />
            <div className="flex items-center gap-2">
              <span style={{ fontSize: 28, lineHeight: 1 }}>
                {currentToy.emoji}
              </span>
              <div className="flex flex-col">
                <span className="font-display text-[10px] uppercase tracking-wider text-bone-300/70">
                  想要
                </span>
                <span className="font-display text-sm font-bold text-ink-900">
                  {currentToy.name}
                </span>
              </div>
            </div>
            {/* 阶段切换提示 */}
            {switching && (
              <motion.span
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                className="ml-2 text-[10px] text-emerald"
              >
                新玩具！
              </motion.span>
            )}
          </motion.div>
        </AnimatePresence>

        {/* 宠物头像 */}
        <motion.div
          animate={{ y: [0, -6, 0] }}
          transition={{ duration: 2.4, repeat: Infinity, ease: "easeInOut" }}
          className="relative"
        >
          <div
            className="grid place-items-center rounded-full"
            style={{
              width: 96,
              height: 96,
              background:
                "radial-gradient(circle at 35% 30%, rgba(255,255,255,0.25) 0%, rgba(0,0,0,0.15) 70%)",
              boxShadow:
                "0 10px 30px -8px rgba(0,0,0,0.5), inset 0 2px 4px rgba(255,255,255,0.2)",
            }}
          >
            <span style={{ fontSize: 56, lineHeight: 1 }}>{avatar}</span>
          </div>
          {/* 阶段徽章 */}
          <div
            className="absolute -right-1 -top-1 grid h-7 w-7 place-items-center rounded-full font-display text-xs font-bold"
            style={{
              background: "linear-gradient(140deg, #F2C75E, #C8902D)",
              color: "#1A1206",
              boxShadow: "0 2px 8px rgba(232,177,74,0.6)",
            }}
          >
            {stage}
          </div>
        </motion.div>
      </div>

      {/* 阶段进度 */}
      <div className="w-full">
        <div className="mb-1 flex items-center justify-between text-[10px] text-bone-300/70">
          <span>阶段进度</span>
          <span>
            {stage} / 2
          </span>
        </div>
        <div className="flex gap-1">
          <div
            className="h-1.5 flex-1 rounded-full"
            style={{
              background:
                stage >= 1
                  ? "linear-gradient(90deg, #3DD9A6, #6FE8C0)"
                  : "rgba(255,255,255,0.08)",
            }}
          />
          <div
            className="h-1.5 flex-1 rounded-full"
            style={{
              background:
                stage >= 2
                  ? "linear-gradient(90deg, #F2C75E, #E8B14A)"
                  : "rgba(255,255,255,0.08)",
            }}
          />
        </div>
      </div>

      {/* 机制提示 / 结算提示 */}
      <div className="w-full text-center text-[11px] text-bone-300/70">
        {settled ? (
          <span className="text-gold-400">本局已结算</span>
        ) : switching ? (
          <span className="text-emerald">第一个玩具完成！宠物想要新的玩具</span>
        ) : (
          <span>{level?.mechanic ?? ""}</span>
        )}
      </div>
    </div>
  );
}
