export type GameView =
  | "hub"
  | "game"
  | "ocean-hub"
  | "rogue-hub"
  | "pet-hub"
  | "build-hub"
  | "build2-hub";
export type GamePhase = "idle" | "swap" | "cascade" | "settled" | "ended";
// Rogue 抽卡子阶段（phase==="ended" 时细分）
export type RogueDrawPhase = "none" | "draw" | "revealed";
// Pet 模式子阶段
export type PetPhase = "playing" | "stage1Done" | "ended";

interface Hint {
  from: { row: number; col: number };
  to: { row: number; col: number };
}

interface GameState {
  // 视图
  view: GameView;
  // 当前模式
  mode: GameMode;
  // 当前关卡 id
  currentLevelId: number;
  // 当前关卡初始水位（仅海洋模式）
  currentWaterStart: number;
  // 当前水位（行索引，仅海洋模式有效）
  waterLevel: number;
  // 棋盘
  grid: Grid;
  // 玩家选中的格子（用于交换）
  selected: { row: number; col: number } | null;
  // 提示的合法交换位置
  hint: Hint | null;
  // 阶段
  phase: GamePhase;
  // 正在清除的格子（视觉高亮）
  clearingCells: { row: number; col: number }[];
  // 海洋模式：正在破坏泳圈的格子（视觉高亮）
  floatersBreaking: { row: number; col: number }[];
  // 当前连锁中触发的特殊类型（用于全屏特效）
  activeEffect: "rainbow" | "bomb" | null;
  // 得分
  score: number;
  // 剩余步数
  movesLeft: number;
  // 当前最大连击
  combo: number;
  // 本局历史连击峰值
  bestComboThisRun: number;
  // 本局所有步骤（用于结算明细）
  runSteps: CascadeStep[];
  // 是否胜利
  won: boolean;
  // 星级
  stars: number;
  // 持久化进度
  progress: Progress;
  // 提示信息（如无可走步自动重洗）
  notice: string | null;

  // Rogue 模式：本 run 全程分数加成比例之和（0.1=+10%，可叠加）
  rogueRunBoost: number;
  // Rogue 模式：下一关单次分数加成比例（进入下一关时消耗）
  rogueNextBoost: number;
  // Rogue 模式：当前关生效的分数乘数（=1+runBoost+nextBoost，关开始时锁定）
  rogueActiveMult: number;
  // Rogue 抽卡子阶段
  rogueDrawPhase: RogueDrawPhase;
  // 本局抽出的 3 张卡
  rogueDrawCards: CardDef[];
  // 玩家选中的卡 id
  roguePickedCardId: string | null;
  // 已生效奖励的摘要文案
  rogueAppliedSummary: string | null;

  // Pet 模式：当前宠物
  petKind: PetKind | null;
  // Pet 模式：当前阶段（1 或 2）
  petToyStage: 1 | 2;
  // Pet 模式：本局 2 个玩具
  petToys: { stage1: Toy; stage2: Toy } | null;
  // Pet 模式：按 color 索引的累计计数（跨阶段累计不清零）
  petPartsCollected: Record<GemColor, number>;
  // Pet 模式子阶段
  petPhase: PetPhase;

  // Build 模式：剩余秒数
  buildTimer: number;
  // Build 模式：本局总时长（秒，用于结算时按 key 存最高分）
  buildTimerDuration: number;
  // Build 模式：各色累计消除数
  buildClearCounts: Record<GemColor, number>;
  // Build 模式：各色 buff 等级
  buildBuffs: Record<GemColor, BuffTier>;
  // Build 模式：当前分数乘数（emerald buff，1.0=无加成）
  buildScoreMult: number;
  // Build 模式：3+消除加时量（ruby buff，0=无加时）
  buildTimeBonus: number;
  // Build 模式：本局是否已结束
  buildEnded: boolean;
  // Build 模式：各色 buff 触发闪光 key（递增计数器）
  buildFlashKey: Record<GemColor, number>;
  // Build 模式：post-buff 效果已应用（防止重复应用 buff）
  buildPostBuffApplied: boolean;
  // Build V2 模式：是否计入 buff 激活计数（仅玩家主动消除为 true）
  buildCountingEnabled: boolean;

  // Actions
  goToHub: () => void;
  goToOceanHub: () => void;
  goToRogueHub: () => void;
  goToPetHub: () => void;
  goToBuildHub: () => void;
  goToBuild2Hub: () => void;
  startLevel: (id: number) => void;
  startOceanLevel: (id: number) => void;
  startRogueRun: () => void;
  startRogueLevel: (id: number) => void;
  pickRogueCard: (cardId: string) => void;
  proceedRogue: () => void;
  startPetLevel: (id: number) => void;
  startBuild: (duration?: number) => void;
  startBuild2: (duration?: number) => void;
  tickBuildTimer: () => void;
  stopBuildTimer: () => void;
  selectCell: (row: number, col: number) => void;
  showHint: () => void;
  restart: () => void;
  nextLevel: () => void;
  resetProgress: () => void;
  clearNotice: () => void;
}

