import { motion, AnimatePresence } from "framer-motion";
import { useGame } from "@/hooks/useGame";
import { BUILD_CONFIG } from "@/game/levels";

interface BuildSettleModalProps {
  open: boolean;
  onHome: () => void;
  onRetry: () => void;
}

export default function BuildSettleModal({
  open,
  onHome,
  onRetry,
}: BuildSettleModalProps) {
  const score = useGame((s) => s.score);
  const stars = useGame((s) => s.stars);
  const buildBuffs = useGame((s) => s.buildBuffs);
  const mode = useGame((s) => s.mode);
  const duration = useGame((s) => s.buildTimerDuration);
  const isBuild2 = mode === "build2";
  const buildBestScores = useGame((s) =>
    isBuild2 ? s.progress.build2BestScores : s.progress.buildBestScores,
  );
  const buildBestScore = buildBestScores[duration] ?? 0;
  const isNewRecord = score >= buildBestScore && score > 0;

  return (
    <AnimatePresence>
      {open && (
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          exit={{ opacity: 0 }}
          className="fixed inset-0 z-50 grid place-items-center bg-black/60 backdrop-blur-sm"
        >
          <motion.div
            initial={{ scale: 0.85, y: 20 }}
            animate={{ scale: 1, y: 0 }}
            exit={{ scale: 0.9, opacity: 0 }}
            transition={{ type: "spring", stiffness: 300, damping: 24 }}
            className="glass w-[90%] max-w-sm rounded-3xl p-6 text-center"
            style={{
              background:
                "linear-gradient(160deg, rgba(61,217,166,0.12) 0%, rgba(59,123,255,0.08) 100%)",
              border: "1px solid rgba(61,217,166,0.25)",
              boxShadow: "0 20px 60px -20px rgba(61,217,166,0.3)",
            }}
          >
            {/* 标题 */}
            <p className="font-display text-[10px] uppercase tracking-[0.3em] text-emerald-300/70">
              {duration} 秒 · 时间到
            </p>
            <h2 className="mt-1 font-display text-2xl font-bold text-bone-50">
              挑战结束
            </h2>

            {/* 星级 */}
            <div className="mt-4 flex justify-center gap-2">
              {[0, 1, 2].map((i) => (
                <motion.span
                  key={i}
                  initial={{ scale: 0, rotate: -30 }}
                  animate={{ scale: 1, rotate: 0 }}
                  transition={{ delay: 0.2 + i * 0.15, type: "spring" }}
                  className={`text-3xl ${i < stars ? "" : "opacity-20 grayscale"}`}
                >
                  ⭐
                </motion.span>
              ))}
            </div>

            {/* 分数 */}
            <div className="mt-4">
              <p className="text-[10px] uppercase tracking-wider text-bone-300/50">
                最终分数
              </p>
              <p className="font-display text-4xl font-bold text-emerald-200">
                {score.toLocaleString()}
              </p>
              {isNewRecord && (
                <motion.p
                  initial={{ opacity: 0, y: -4 }}
                  animate={{ opacity: 1, y: 0 }}
                  className="mt-1 text-xs font-bold text-amber-300"
                >
                  🎉 新纪录！
                </motion.p>
              )}
            </div>

            {/* 已解锁 buff */}
            <div className="mt-4">
              <p className="mb-2 text-[10px] uppercase tracking-wider text-bone-300/50">
                已解锁 buff
              </p>
              <div className="flex flex-wrap justify-center gap-1">
                {BUILD_CONFIG.buffs.map((cfg) => {
                  const tier = buildBuffs[cfg.color];
                  if (tier === 0) return null;
                  return (
                    <div
                      key={cfg.color}
                      className="flex items-center gap-1 rounded-lg bg-white/5 px-2 py-1"
                      style={{
                        borderColor:
                          tier === 2
                            ? "rgba(255,210,59,0.3)"
                            : "rgba(61,217,166,0.25)",
                        borderWidth: 1,
                      }}
                    >
                      <span className="text-sm">{cfg.partEmoji}</span>
                      <span className="text-[10px] text-bone-200">
                        {tier === 2 ? cfg.nameT2 : cfg.nameT1}
                      </span>
                    </div>
                  );
                })}
                {Object.values(buildBuffs).every((t) => t === 0) && (
                  <p className="text-xs text-bone-400/50">未解锁任何 buff</p>
                )}
              </div>
            </div>

            {/* 按钮 */}
            <div className="mt-6 flex gap-3">
              <button
                onClick={onHome}
                className="flex-1 rounded-xl border border-white/10 bg-white/5 py-2.5 text-sm font-medium text-bone-200 transition hover:bg-white/10"
              >
                返回
              </button>
              <button
                onClick={onRetry}
                className="flex-1 rounded-xl py-2.5 text-sm font-bold text-emerald-50 transition"
                style={{
                  background:
                    "linear-gradient(120deg, rgba(61,217,166,0.3) 0%, rgba(59,123,255,0.2) 100%)",
                  border: "1px solid rgba(61,217,166,0.4)",
                }}
              >
                再来一局
              </button>
            </div>
          </motion.div>
        </motion.div>
      )}
    </AnimatePresence>
  );
}
