import { starsForScore } from "./levels";

export interface ScoreBreakdown {
  base: number;
  cascadeBonus: number;
  specialBonus: number;
  total: number;
}

// 由步骤构建得分明细（用于结算界面展示）
export function buildBreakdown(
  steps: { cleared: { row: number; col: number }[]; scoreGained: number; cascadeIndex: number; triggeredKinds: string[] }[],
): ScoreBreakdown {
  let base = 0;
  let cascadeBonus = 0;
  let specialBonus = 0;

  for (const step of steps) {
    const cells = step.cleared.length;
    const stepBase = cells * 30;
    const mult = 1 + step.cascadeIndex * 0.2;
    const stepCascade = Math.round(stepBase * mult) - stepBase;
    const stepRemain = step.scoreGained - stepBase - stepCascade;
    base += stepBase;
    cascadeBonus += stepCascade;
    specialBonus += Math.max(0, stepRemain);
  }
  return {
    base,
    cascadeBonus,
    specialBonus,
    total: base + cascadeBonus + specialBonus,
  };
}

export { starsForScore };
