import { motion } from "framer-motion";
import { ArrowLeft, ChevronRight, Waves, LifeBuoy, Droplet, TrendingDown } from "lucide-react";
import { OCEAN_LEVELS } from "@/game/levels";
import { useGame } from "@/hooks/useGame";
import LevelCard from "./LevelCard";

interface OceanHubProps {
  onStart: (id: number) => void;
}

export default function OceanHub({ onStart }: OceanHubProps) {
  const progress = useGame((s) => s.progress);
  const goToHub = useGame((s) => s.goToHub);

  const oceanUnlocked = progress.oceanUnlocked;
  const oceanStars = Object.values(progress.oceanRecords).reduce(
    (sum, r) => sum + (r?.stars ?? 0),
    0,
  );

  return (
    <div className="relative mx-auto flex w-full max-w-6xl flex-col gap-8 px-6 py-10">
      {/* 返回 */}
      <motion.button
        type="button"
        onClick={goToHub}
        initial={{ opacity: 0, x: -8 }}
        animate={{ opacity: 1, x: 0 }}
        transition={{ duration: 0.4 }}
        className="flex items-center gap-2 self-start text-sm text-bone-300/80 transition hover:text-cyan-200"
      >
        <ArrowLeft size={16} />
        返回主界面
      </motion.button>

      {/* Hero */}
      <motion.header
        initial={{ opacity: 0, y: 16 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.7, ease: "easeOut" }}
        className="flex flex-col items-center gap-3 pt-2 text-center"
      >
        <motion.div
          initial={{ letterSpacing: "0.6em", opacity: 0 }}
          animate={{ letterSpacing: "0.18em", opacity: 1 }}
          transition={{ duration: 1.1, ease: "easeOut" }}
          className="flex items-center gap-4"
        >
          <motion.span
            initial={{ rotate: -10, opacity: 0 }}
            animate={{ rotate: [-10, 10, -10], opacity: 1 }}
            transition={{
              rotate: { duration: 4, repeat: Infinity, ease: "easeInOut" },
              opacity: { duration: 0.8 },
            }}
          >
            <Waves size={36} className="text-cyan-200" />
          </motion.span>
          <h1 className="font-display text-5xl font-black tracking-[0.18em] text-bone-50 sm:text-6xl">
            深海
          </h1>
        </motion.div>
        <p className="font-display text-xl italic tracking-[0.3em] text-cyan-200/90 sm:text-2xl">
          Abyssal
        </p>
        <p className="mt-1 max-w-md text-sm text-bone-300/80">
          上浮物理 · 水位随得分退却 · 泳圈破坏优先
        </p>
      </motion.header>

      {/* 进度面板 */}
      <motion.section
        initial={{ opacity: 0, y: 12 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.6, delay: 0.25 }}
        className="grid grid-cols-2 gap-4 sm:grid-cols-2"
      >
        <div
          className="flex items-center gap-3 rounded-2xl p-4"
          style={{
            background:
              "linear-gradient(180deg, rgba(120,220,255,0.10), rgba(46,140,171,0.04))",
            border: "1px solid rgba(120,220,255,0.18)",
          }}
        >
          <div className="grid h-9 w-9 place-items-center rounded-lg bg-ink-700/60">
            <Waves size={16} className="text-cyan-200" />
          </div>
          <div>
            <p className="font-display text-[10px] uppercase tracking-[0.25em] text-cyan-200/70">
              已解锁
            </p>
            <p className="font-display text-2xl font-bold leading-none text-bone-50">
              {oceanUnlocked - 1} / {OCEAN_LEVELS.length}
            </p>
          </div>
        </div>
        <div
          className="flex items-center gap-3 rounded-2xl p-4"
          style={{
            background:
              "linear-gradient(180deg, rgba(120,220,255,0.10), rgba(46,140,171,0.04))",
            border: "1px solid rgba(120,220,255,0.18)",
          }}
        >
          <div className="grid h-9 w-9 place-items-center rounded-lg bg-ink-700/60">
            <Droplet size={16} className="text-cyan-200" />
          </div>
          <div>
            <p className="font-display text-[10px] uppercase tracking-[0.25em] text-cyan-200/70">
              累计星级
            </p>
            <p className="font-display text-2xl font-bold leading-none text-bone-50">
              {oceanStars} / {OCEAN_LEVELS.length * 3}
            </p>
          </div>
        </div>
      </motion.section>

      {/* 关卡轨道 */}
      <motion.section
        initial={{ opacity: 0, y: 12 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.6, delay: 0.4 }}
      >
        <div className="mb-3 flex items-center justify-between">
          <h3 className="font-display text-lg font-semibold tracking-widest text-bone-100">
            海洋关卡
          </h3>
        </div>
        <div className="scroll-track flex gap-4 overflow-x-auto pb-4">
          {OCEAN_LEVELS.map((l) => {
            const record = progress.oceanRecords[l.id];
            const isCurrent = l.id === oceanUnlocked;
            return (
              <LevelCard
                key={`ocean-${l.id}`}
                levelId={l.id}
                unlocked={l.id <= oceanUnlocked}
                stars={record?.stars ?? 0}
                bestScore={record?.bestScore ?? 0}
                isCurrent={isCurrent}
                onSelect={onStart}
              />
            );
          })}
          <div className="flex w-40 shrink-0 items-center justify-center text-bone-300/40">
            <div className="text-center">
              <ChevronRight size={24} className="mx-auto mb-1 opacity-40" />
              <p className="text-[10px] uppercase tracking-widest">更多即将到来</p>
            </div>
          </div>
        </div>
      </motion.section>

      {/* 玩法说明 */}
      <motion.section
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        transition={{ duration: 0.6, delay: 0.55 }}
        className="rounded-2xl p-5"
        style={{
          background:
            "linear-gradient(180deg, rgba(46,140,171,0.14), rgba(20,80,120,0.04))",
          border: "1px solid rgba(120,220,255,0.18)",
        }}
      >
        <h3 className="mb-3 font-display text-sm font-semibold uppercase tracking-[0.3em] text-cyan-100">
          海洋规则
        </h3>
        <ul className="grid gap-2 text-xs text-bone-300/85 sm:grid-cols-2">
          <li className="flex items-start gap-2">
            <TrendingDown size={14} className="mt-0.5 shrink-0 text-cyan-200" />
            <span>消除后下方棋子上浮填充，底部补充新棋子（与常规下落相反）。</span>
          </li>
          <li className="flex items-start gap-2">
            <Droplet size={14} className="mt-0.5 shrink-0 text-cyan-200" />
            <span>水位随得分进度退却，棋盘逐渐浮出水面，分隔水上水下两景。</span>
          </li>
          <li className="flex items-start gap-2">
            <LifeBuoy size={14} className="mt-0.5 shrink-0 text-amber-300" />
            <span>带「泳圈」的棋子在三消时优先破坏泳圈，棋子保留并参与后续匹配。</span>
          </li>
          <li className="flex items-start gap-2">
            <Waves size={14} className="mt-0.5 shrink-0 text-cyan-200" />
            <span>每次连锁结束后有概率投放新泳圈，挑战随关卡推进而加剧。</span>
          </li>
        </ul>
      </motion.section>
    </div>
  );
}
